#include<stdlib.h>

typedef struct StackElement StackElement;
struct StackElement
{
    void *data;
    StackElement *below; // When this element is popped, below becomes top element.
};

struct Stack
{
    StackElement *bottom;
    StackElement *top;
    size_t size;
};
typedef struct Stack Stack;

Stack *stack_create();
void stack_free(Stack *stack);
void stack_push(Stack *s, void *);
// Pop the top element.
void *stack_pop(Stack *s);
// Get the data of the top element without popping (NULL if the stack is empty).
void *stack_top(Stack *s);
// Pull the bottom element.
void *stack_rock(Stack *s);

