// PART H XML_DOM ////////////////////////////////////////

/*
    The native xmq DOM. It replaces the libxml2 tree (xmlDoc/xmlNode/xmlAttr/xmlNs/xmlDtd).

    All data structures are opaque: they are defined in xml_dom.c only and are
    accessed through the functions below. The node type is the struct XMQNode
    that xmq.h declares as opaque and the attribute type is struct XMQAttr.
    An attribute is also a node: xml_attr_node/xml_node_as_attr convert between
    the two (xpath node sets contain attributes as nodes). The DTD, entity
    declarations and element/attribute/notation declarations are nodes too.

    All char* are UTF-8 encoded and zero terminated unless a length is given.
    The parsers validate and convert input, the dom assumes valid UTF-8.

    Ownership rules:
    - A tree is owned by an XmlDom. Every node belongs to a dom.
    - All strings are copied into the dom, returned const char* point into the
      dom and are valid until the node is changed or freed. Functions returning
      char* return malloced strings that the caller frees.
    - Namespaces (XmlNs) are reference counted. An element owns the namespaces
      declared on it and every node using a namespace holds a reference to it.
      Thus moving or copying subtrees never leaves dangling namespace pointers.
      After a move/copy, call xml_node_reconcile_ns to make sure all used
      namespaces are also declared in scope.
    - xml_node_add_child merges adjacent text nodes (like libxml2 xmlAddChild),
      in which case the added node is freed and the existing node is returned.
      Use xml_node_append_child to never merge.
    - An attribute value is stored as children of the attribute: text nodes and
      entity references (like libxml2), since xmq keeps &entity; references
      also inside attribute values.
    - An entity reference has no content of its own and, since entities are
      never expanded implicitly, contributes nothing to string values. A
      character reference kept as a reference node (name "#10" or "#x41", xmq
      can keep them) is a character: it contributes the character.
    - The DTD (doctype) is a child of the document node. Its children are the
      entity/element/attribute declarations (and comments/pis) in source order.
      Notations are kept in a separate list, as libxml2 does, since they are
      serialized first.

    There is a single dom for xml and html: html is only a choice of parser and serializer,
    never a different node or document type.

*/

#include"xmq.h"

#include<stdbool.h>
#include<stddef.h>
#include<stdint.h>

typedef enum
{
    XML_DOM_ELEMENT = 1,
    XML_DOM_ATTRIBUTE = 2,
    XML_DOM_TEXT = 3,
    XML_DOM_CDATA = 4,
    XML_DOM_ENTITY_REF = 5,
    XML_DOM_PI = 7,
    XML_DOM_COMMENT = 8,
    XML_DOM_DOCUMENT = 9,
    XML_DOM_DTD = 14,
    XML_DOM_ELEMENT_DECL = 15,
    XML_DOM_ATTRIBUTE_DECL = 16,
    XML_DOM_ENTITY_DECL = 17,
    /** An xpath namespace node (namespace:: axis). Not part of any tree: its parent is the
        element it belongs to, but it is not one of the element's children. */
    XML_DOM_NAMESPACE = 18,
    XML_DOM_NOTATION_DECL = 20,
    /** A parameter entity reference %name; between declarations in the dtd (never expanded). */
    XML_DOM_PE_REF = 21,
} XmlNodeKind;

typedef enum
{
    XML_ENTITY_INTERNAL_GENERAL = 1,
    XML_ENTITY_EXTERNAL_GENERAL_PARSED = 2,
    XML_ENTITY_EXTERNAL_GENERAL_UNPARSED = 3,
    XML_ENTITY_INTERNAL_PARAMETER = 4,
    XML_ENTITY_EXTERNAL_PARAMETER = 5,
} XmlEntityType;

/** A document tree. */
struct XmlDom;
typedef struct XmlDom XmlDom;

/** A namespace binding prefix -> href. */
struct XmlNs;
typedef struct XmlNs XmlNs;

#define XML_DOM_XML_NAMESPACE "http://www.w3.org/XML/1998/namespace"

// Dom ////////////////////////////////////////////////////////////

XmlDom *xml_dom_new();
void xml_dom_free(XmlDom *dom);
/** The document node, kind XML_DOM_DOCUMENT. Its children are the top level nodes. */
XMQNode *xml_dom_document(XmlDom *dom);
/** The first element child of the document node, or NULL. */
XMQNode *xml_dom_root_element(XmlDom *dom);
/** Replace the root element (the old one is freed). */
void xml_dom_set_root_element(XmlDom *dom, XMQNode *root);
/** Version from the xml declaration, eg "1.0". NULL if none. */
const char *xml_dom_version(const XmlDom *dom);
void xml_dom_set_version(XmlDom *dom, const char *version);
/** Encoding from the xml declaration. NULL if none. */
const char *xml_dom_encoding(const XmlDom *dom);
/** Where the document was loaded from (libxml2 doc->URL), or NULL. */
const char *xml_dom_url(const XmlDom *dom);
void xml_dom_set_url(XmlDom *dom, const char *url);
void xml_dom_set_encoding(XmlDom *dom, const char *encoding);
/** Standalone from the xml declaration: -1 not given, 0 no, 1 yes. */
int xml_dom_standalone(const XmlDom *dom);
void xml_dom_set_standalone(XmlDom *dom, int standalone);

// DTD ////////////////////////////////////////////////////////////

/** Get the DTD (doctype) node, kind XML_DOM_DTD, or NULL. */
XMQNode *xml_dom_dtd(XmlDom *dom);
/** Create (or replace) the DTD of the dom. It is inserted before the root element, or last. */
XMQNode *xml_dom_set_dtd(XmlDom *dom, const char *name, const char *public_id, const char *system_id);
const char *xml_dtd_public_id(const XMQNode *dtd);
const char *xml_dtd_system_id(const XMQNode *dtd);
/** Add an entity declaration. Returns NULL if an entity of the same kind and name already exists (first wins). */
XMQNode *xml_dtd_add_entity(XMQNode *dtd, const char *name, XmlEntityType etype,
                            const char *public_id, const char *system_id,
                            const char *notation, const char *content, const char *orig);
/** Add an element/attribute declaration as preformatted text without the final ">\n". */
XMQNode *xml_dtd_add_decl(XMQNode *dtd, XmlNodeKind kind, const char *name, const char *text, const char *default_value);
/** Add a notation declaration (text without the final ">\n"). Duplicates are ignored, returns NULL. */
XMQNode *xml_dtd_add_notation(XMQNode *dtd, const char *name, const char *text);
/** Add a parameter entity reference %name; between the declarations. */
XMQNode *xml_dtd_add_pe_ref(XMQNode *dtd, const char *name);
/** Iterate the notations with xml_node_next. */
XMQNode *xml_dtd_first_notation(const XMQNode *dtd);
/** True if the dtd has any declarations or parameter entity references (comments/pis do not count). */
bool xml_dtd_has_declarations(const XMQNode *dtd);
/** Find a general entity declaration in the dom's dtd. */
XMQNode *xml_dom_get_entity(XmlDom *dom, const char *name);
/** Find a parameter entity declaration in the dom's dtd. */
XMQNode *xml_dom_get_parameter_entity(XmlDom *dom, const char *name);
/** Entity declaration accessors. The value (char refs expanded) is xml_node_content. */
XmlEntityType xml_entity_decl_type(const XMQNode *decl);
/** The literal value as written, without quotes (NULL if unknown). */
const char *xml_entity_decl_orig(const XMQNode *decl);
const char *xml_entity_decl_public_id(const XMQNode *decl);
const char *xml_entity_decl_system_id(const XMQNode *decl);
/** NDATA notation name for unparsed entities. */
const char *xml_entity_decl_notation(const XMQNode *decl);
/** Element/attribute/notation declarations: the preformatted text is xml_node_content.
    An attribute declaration can have a default value, that is escaped when serialized. */
const char *xml_decl_default_value(const XMQNode *decl);

// Node creation //////////////////////////////////////////////////

XMQNode *xml_node_new_element(XmlDom *dom, const char *name, XmlNs *ns);
XMQNode *xml_node_new_text(XmlDom *dom, const char *text);
XMQNode *xml_node_new_text_len(XmlDom *dom, const char *text, size_t len);
XMQNode *xml_node_new_cdata(XmlDom *dom, const char *text, size_t len);
/** A comment. text NULL gives a comment without content (serialized as nothing). */
XMQNode *xml_node_new_comment(XmlDom *dom, const char *text);
/** A processing instruction. data may be NULL (serialized as <?target?>). */
XMQNode *xml_node_new_pi(XmlDom *dom, const char *target, const char *data);
/** An entity reference &name; */
XMQNode *xml_node_new_entity_ref(XmlDom *dom, const char *name);

/** A namespace node for xpath, name = prefix (NULL for the default namespace), content = href.
    index orders the namespace nodes of the same element (stored as the node line). Free with xml_node_free. */
XMQNode *xml_node_new_namespace_node(XMQNode *element, const char *prefix, const char *href, int index);

/** Unlink and free the node and its subtree. */
void xml_node_free(XMQNode *node);

// Node accessors /////////////////////////////////////////////////

XmlNodeKind xml_node_kind(const XMQNode *node);
XmlDom *xml_node_dom(const XMQNode *node);
/** The parent node. For an attribute this is the owner element. */
XMQNode *xml_node_parent(const XMQNode *node);
XMQNode *xml_node_first_child(const XMQNode *node);
XMQNode *xml_node_last_child(const XMQNode *node);
/** The next sibling. For attributes the next attribute, for notations the next notation. */
XMQNode *xml_node_next(const XMQNode *node);
XMQNode *xml_node_prev(const XMQNode *node);
/** Element/attribute local name, pi target, entity name, dtd name, declaration name. */
const char *xml_node_name(const XMQNode *node);
void xml_node_set_name(XMQNode *node, const char *name);
/** The raw content of a text/cdata/comment/pi node or a declaration. NULL for elements, attributes, entity refs. */
const char *xml_node_content(const XMQNode *node);
/** Set the raw content of a leaf node. For elements/attributes/document: replace all children with one text node. */
void xml_node_set_content(XMQNode *node, const char *content);
/** Append to the content of a leaf node (text/cdata/comment/pi). */
void xml_node_append_content(XMQNode *node, const char *content, size_t len);
/** The XPath string-value of the node: the text of the descendant text/cdata nodes, entity references
    contribute nothing. Always malloced, never NULL. */
char *xml_node_string_value(const XMQNode *node);
bool xml_node_is_element(const XMQNode *node);
bool xml_node_is_text(const XMQNode *node);
/** The namespace of an element or attribute, NULL if none. */
XmlNs *xml_node_ns(const XMQNode *node);
/** Namespace uri of the element/attribute, NULL if none (an xmlns="" undeclaration is also NULL). */
const char *xml_node_ns_uri(const XMQNode *node);
const char *xml_node_ns_prefix(const XMQNode *node);
/** Source line, 0 if unknown. */
int xml_node_line(const XMQNode *node);
void xml_node_set_line(XMQNode *node, int line);
/** Free for use by callers, never touched by the dom (replaces libxml2 _private). Not copied. */
void *xml_node_user_data(const XMQNode *node);
void xml_node_set_user_data(XMQNode *node, void *user_data);

// Tree editing ///////////////////////////////////////////////////

/** Append child last, no text merging. Child is unlinked first. Returns child. */
XMQNode *xml_node_append_child(XMQNode *parent, XMQNode *child);
/** Append child last, merging text with a preceding text node (then child is freed). Returns the resulting node. */
XMQNode *xml_node_add_child(XMQNode *parent, XMQNode *child);
/** Insert n before node. Returns n. */
XMQNode *xml_node_add_prev_sibling(XMQNode *node, XMQNode *n);
/** Insert n after node. Returns n. */
XMQNode *xml_node_add_next_sibling(XMQNode *node, XMQNode *n);
/** Detach node from its parent and siblings. Attributes are detached from their owner. */
void xml_node_unlink(XMQNode *node);
/** Put n where node is and unlink node (node is not freed). Returns node. */
XMQNode *xml_node_replace(XMQNode *node, XMQNode *n);
/** Deep (or shallow) copy node into dom. The copy is unlinked. Namespaces are shared refs, use reconcile.
    Attributes are always copied with their values. A DTD is always copied deep. */
XMQNode *xml_node_copy(XmlDom *dom, const XMQNode *node, bool deep);
size_t xml_node_num_children(const XMQNode *node);
/** Compare document order: <0 a before b, 0 same, >0 a after b. Nodes in different trees compare by address. */
int xml_node_compare_order(const XMQNode *a, const XMQNode *b);

// Attributes /////////////////////////////////////////////////////

/** Set or replace attribute with local name and namespace (ns may be NULL). The value becomes one text child. */
XMQAttr *xml_node_set_attr(XMQNode *element, const char *name, XmlNs *ns, const char *value);
/** Find attribute by local name and namespace uri (NULL uri means no namespace). */
/** Move an attribute (from any element) to the end of the element's attributes, replacing an attribute
    with the same name and namespace. The namespace of the attribute must be in scope (see xml_node_reconcile_ns). */
XMQAttr *xml_node_move_attr(XMQNode *element, XMQAttr *attr);
/** Append an attribute without checking for an existing one with the same name (like libxml2 xmlNewProp),
    used by parsers that resolve namespaces later. value may be NULL for no value. */
XMQAttr *xml_node_append_attr(XMQNode *element, const char *name, XmlNs *ns, const char *value);
XMQAttr *xml_node_get_attr(const XMQNode *element, const char *name, const char *ns_uri);
/** Remove and free the attribute. Returns true if found. */
bool xml_node_remove_attr(XMQNode *element, const char *name, const char *ns_uri);
XMQAttr *xml_node_first_attr(const XMQNode *element);
XMQAttr *xml_attr_next(const XMQAttr *attr);
const char *xml_attr_name(const XMQAttr *attr);
/** The value if it is a single text node (or "" if empty), NULL if the value contains entity references.
    Use xml_node_string_value for the text without the entity references. */
const char *xml_attr_simple_value(const XMQAttr *attr);
XMQNode *xml_attr_owner(const XMQAttr *attr);
/** An attribute as a node (its children are the value). */
XMQNode *xml_attr_node(XMQAttr *attr);
/** A node as an attribute, NULL if it is not an attribute. */
XMQAttr *xml_node_as_attr(XMQNode *node);

// Namespaces /////////////////////////////////////////////////////

/** NULL for the default namespace. */
const char *xml_ns_prefix(const XmlNs *ns);
/** "" for an undeclaration xmlns="". */
/** The uri, "" for an undeclaration (xmlns=""), NULL for a prefix declared without uri (xmq allows that). */
const char *xml_ns_href(const XmlNs *ns);
/** The namespaces declared on an element, iterate with xml_ns_next_decl. */
XmlNs *xml_node_first_ns_decl(const XMQNode *element);
XmlNs *xml_ns_next_decl(const XmlNs *ns);
/** Declare prefix->href on element. Returns NULL if prefix is already declared there. */
XmlNs *xml_ns_declare(XMQNode *element, const char *prefix, const char *href);
/** Set the namespace of an element or attribute (the ref count is managed). */
void *xml_ns_user_data(const XmlNs *ns);
void xml_ns_set_user_data(XmlNs *ns, void *user_data);
/** Move the declaration ns of element last among the element's declarations. */
void xml_ns_move_decl_last(XMQNode *element, XmlNs *ns);
/** Move the declaration ns (the same object, users keep pointing at it) from the element from
    to the front of the declarations of to (an ancestor), like libxslt moving excluded
    namespaces to the root. Duplicate prefixes on to are not checked. */
void xml_ns_move_decl_to(XMQNode *from, XmlNs *ns, XMQNode *to);
/** Remove the declaration ns from element, the element and its descendants (and attributes) that use ns
    are changed to use replacement (which may be NULL, it must be in scope). */
void xml_ns_remove_decl(XMQNode *element, XmlNs *ns, XmlNs *replacement);
/** Change the href of a declaration, used while parsing when an xmlns attribute follows its first use. */
void xml_ns_set_href(XmlNs *ns, const char *href);
void xml_node_set_ns(XMQNode *node, XmlNs *ns);
/** Find the in scope declaration of prefix (NULL = default namespace), walking ancestors. "xml" is predefined. */
XmlNs *xml_ns_lookup_prefix(const XMQNode *node, const char *prefix);
/** Find an in scope declaration of href whose prefix is not shadowed by a closer declaration. */
XmlNs *xml_ns_lookup_href(const XMQNode *node, const char *href);
/** Declare (on the node itself) every namespace used in the subtree that is not in scope. */
void xml_node_reconcile_ns(XMQNode *node);

/** Split "{prefix}uri" into prefix (malloced, or NULL) and uri. Returns NULL on a missing '}'. */
const char *xml_ns_split_puri(const char *puri, char **out_prefix);
/** Apply an xmq.h XMQNS action to a new element (already linked into its parent). */
XMQStatus xml_node_apply_xmqns(XMQNode *element, XMQNS ns);
/** Set an attribute using an xmq.h XMQNS action (NS_HERE is not allowed for attributes). */
XMQReturnAttr xml_node_set_attr_xmqns(XMQNode *element, const char *name, const char *value, XMQNS ns);

#define XML_DOM_MODULE

// PART H XML_PARSER ////////////////////////////////////////

/*
    XML 1.0 + Namespaces parser building the native dom (xml_dom.h).

    It builds the same tree as libxml2 xmlReadMemory does with the options libxmq
    uses (XML_PARSE_NOCDATA | XML_PARSE_NONET, optionally XML_PARSE_NOBLANKS):
    entity references are kept as nodes (also in attribute values), character
    references and the predefined entities are expanded, the internal subset is
    parsed into declaration nodes, external subsets/entities are never loaded.

    There is no global state: everything is configured through XmlParseSettings
    and messages are reported through the callback in the settings.

    Declared entities (&name; and %name;) are never expanded, they stay as reference
    nodes until an explicit xmqExpandEntities, which is where entity loops, nesting
    and amplification limits are enforced. Only character references and the five
    predefined entities (lt gt amp apos quot) are decoded while parsing. Entity
    references in namespace uris are rejected, since a uri is a plain string.

    The input is UTF-8, UTF-16 (bom or "<?" pattern) or ISO-8859-1 (declared),
    a UTF-8 BOM is skipped; the dom gets UTF-8.
*/

#ifndef BUILDING_DIST_XMQ
#include"xml_dom.h"
#endif

#include<stdbool.h>
#include<stddef.h>

/** Called for non-fatal problems (eg namespace errors) that libxml2 reports but recovers from.
    message is a complete libxml2 style message including the source context lines. */
typedef void (*XmlParseMessageCallback)(void *user_data, const char *message);

typedef struct
{
    /** Name used in messages, eg the file name. NULL gives "noname.xml". */
    const char *source_name;
    /** Drop ignorable blank text nodes (libxml2 XML_PARSE_NOBLANKS heuristic). */
    bool no_blanks;
    /** Merge cdata sections into text (XML_PARSE_NOCDATA). */
    bool no_cdata;
    /** Add the attributes defaulted in the dtd to the elements (XML_PARSE_DTDATTR). */
    bool dtd_attr;
    /** Maximum element nesting depth. */
    size_t max_depth;
    /** Maximum length in bytes of a name. */
    size_t max_name_length;
    /** Maximum length in bytes of a single text node, attribute value, comment or pi. */
    size_t max_text_length;
    /** Maximum ratio between expanded entity values and the input size (and at least 1MB). */
    size_t max_amplification;
    /** Receives non-fatal messages, may be NULL. */
    XmlParseMessageCallback message_callback;
    void *message_user_data;
} XmlParseSettings;

/** Fill in the defaults: libxml2's default limits (depth 256, names 50000 bytes,
    text 10000000 bytes, amplification 5), no_blanks and no_cdata false. */
void xml_parse_settings_default(XmlParseSettings *settings);

typedef struct
{
    /** Malloced libxml2 style message with source context, NULL if no error. */
    char *message;
    /** The message without location and context, malloced, NULL if no error. */
    char *short_message;
    /** 1-based line and column (in bytes) of the error. */
    size_t line;
    size_t col;
} XmlParseError;

/** Parse a complete document. Returns NULL on a fatal error, then error (if not NULL)
    is filled in; free it with xml_parse_error_free. */
XmlDom *xml_parse_buffer(const char *start, const char *stop, const XmlParseSettings *settings, XmlParseError *error);

void xml_parse_error_free(XmlParseError *error);

/** Format a parser message like libxml2: "source:line: kind : msg", then the line of s around
    pos (at most 80 bytes) and a ^ under pos. The column of the ^ (from 1) is stored in out_col
    if not NULL. Returns a malloced string. */
char *xml_parser_format_message(const char *source, size_t line, const char *kind, const char *msg,
                                const char *s, size_t len, size_t pos, size_t *out_col);

/**
    Replace every reference to a declared internal general entity below node (the whole
    document if node is NULL), also inside attribute values, with its replacement text
    parsed as content, like libxml2 does with XML_PARSE_NOENT. If only is not NULL, only
    references to that entity are replaced (and everything inside its replacement text).
    Nested references are expanded too. Character reference nodes, undeclared entities
    and external entities (never loaded) are kept as references. Adjacent text nodes
    are merged.

    The limits of libxml2 are enforced: loops, 19 nested entities (20 inputs counting
    the document) and the amplification factor (settings->max_amplification, input_size
    is the size of the parsed source) once more than 1MB has been expanded. On an error
    false is returned and error is filled in, the references expanded so far stay
    expanded.
*/
bool xml_expand_entities(XmlDom *dom, XMQNode *node, const char *only, size_t input_size,
                         const XmlParseSettings *settings, XmlParseError *error);

/** True if the code point is allowed in an xml document (the production Char). */
bool xml_is_valid_char(int c);
/** True if the utf-8 name is an xml Name (with allow_colon) or an NCName. */
bool xml_is_valid_name(const char *name, bool allow_colon);

#define XML_PARSER_MODULE

// PART H XML_SAVE ////////////////////////////////////////

/*
    XML serializer for the native dom (xml_dom.h).

    The output is byte compatible with libxml2's xmlsave.c (the libxmq fork in
    3rdparty/libxml2): xml_save_doc corresponds to xmlDocDumpFormatMemoryEnc
    and xml_save_node to xmlNodeDump. Not yet supported: the XHTML
    serialization mode that libxml2 picks when the doctype is an XHTML DTD.
*/

#ifndef BUILDING_DIST_XMQ
#include"xml_dom.h"
#include"membuffer.h"
#endif

#include<stdbool.h>
#include<stddef.h>

/** Serialize the document. encoding NULL means use the dom's encoding; if that is NULL too,
    no encoding is declared and all non-ascii characters are written as character references. */
void xml_save_doc_to(MemBuffer *mb, XmlDom *dom, const char *encoding, bool format);
/** Same as xml_save_doc_to but returns a malloced zero terminated string, length in *out_len (may be NULL). */
char *xml_save_doc(XmlDom *dom, const char *encoding, bool format, size_t *out_len);

/** Serialize a node and its subtree (UTF-8, no xml declaration). */
void xml_save_node_to(MemBuffer *mb, const XMQNode *node, int level, bool format);
char *xml_save_node(const XMQNode *node, int level, bool format, size_t *out_len);

/** Serialize a node like libxml2 xmlNodeDumpOutput: in the XHTML mode if the dtd of doc is an
    XHTML 1.0 dtd. Text is written in UTF-8 (transcode afterwards for other encodings);
    encoding (NULL is UTF-8) is only used for the XHTML meta tag. */
void xml_save_node_dump_output(MemBuffer *mb, XmlDom *doc, const XMQNode *node, int level, bool format, const char *encoding);
/** Is the output encoding supported by xml_save_transcode (UTF-8, ISO-8859-1, ASCII, UTF-16)? */
bool xml_save_encoding_supported(const char *encoding);
/** Append the utf8 text converted to the encoding, characters the encoding cannot represent
    become decimal character references (like libxml2 output encoders). Returns false (and
    appends nothing) if the encoding is not supported. */
bool xml_save_transcode(MemBuffer *out, const char *utf8, size_t len, const char *encoding);
/** Append s escaped for an xml attribute value (xmlSerializeText with XML_ESCAPE_ATTR),
    non ascii characters are written as character references if escape_non_ascii. */
void xml_save_escape_attr(MemBuffer *mb, const char *s, bool escape_non_ascii);

/** Append s quoted with " (or ' if s contains " but not '), like xmlOutputBufferWriteQuotedString. */
void xml_save_write_quoted(MemBuffer *mb, const char *s);

#define XML_SAVE_MODULE

// PART H XML_HTML ////////////////////////////////////////

/*
    Html knowledge shared by the html parser (xml_html_parser) and the html
    serializer (xml_html_save): element properties, implicit closing rules and
    the html5 named character references. The tables in xml_html.c are
    generated from libxml2 by scripts/generate_xml_html_tables.py.

    There is no html specific dom: the html parser builds the same XmlDom as the
    xml parser, these tables are only used while reading and writing html.
*/

#include<stdbool.h>
#include<stddef.h>

/** Raw text modes of elements, like libxml2 private/html.h. */
#define XML_HTML_DATA_RCDATA 1
#define XML_HTML_DATA_RAWTEXT 2
#define XML_HTML_DATA_PLAINTEXT 3
#define XML_HTML_DATA_SCRIPT 4
#define XML_HTML_DATA_SCRIPT_ESC1 5
#define XML_HTML_DATA_SCRIPT_ESC2 6

typedef struct
{
    const char *name;
    char end_tag;   // 1 the end tag can be implied, 2 forbidden (empty), 3 stylistic, closed easily.
    char empty;     // An empty element (br, img, ...).
    char isinline;  // An inline (1) or block (0) element.
    char data_mode; // 0 or one of XML_HTML_DATA_*.
} XmlHtmlElementDesc;

/** Look up an html element (case insensitive), NULL if unknown. */
const XmlHtmlElementDesc *xml_html_element(const char *name);
/** Does a start tag new_tag implicitly close an open element old_tag? (lowercase names) */
bool xml_html_start_closes(const char *new_tag, const char *old_tag);
/** The end tag priority: an end tag only closes elements with lower or equal priority. */
int xml_html_end_priority(const char *name);
/** Elements where ignorable whitespace is kept since they allow pcdata. */
bool xml_html_allows_pcdata(const char *name);
/** Attributes written in minimized form, eg checked or selected (case insensitive). */
bool xml_html_is_boolean_attr(const char *name);
/**
    Find the longest html5 named character reference that is a prefix of string (which
    starts after the &). Returns the utf8 replacement (length in *rlen) and the number
    of bytes of the reference (excluding the &, including a ; if present) in *nlen,
    or NULL if there is none.
*/
const unsigned char *xml_html_find_entity_prefix(const unsigned char *string, size_t slen, bool is_attr,
                                                 size_t *nlen, size_t *rlen);

#ifndef XMQ_NO_HTML
#define XML_HTML_MODULE
#endif

// PART H XML_HTML_PARSER ////////////////////////////////////////

/*
    Html parser building the native dom (xml_dom.h), the same dom as the xml
    parser builds: there is no html specific node or document type.

    It builds the same tree as libxml2 htmlReadMemory (the libxmq fork in
    3rdparty/libxml2) does with the options libxmq uses (HTML_PARSE_NOERROR |
    HTML_PARSE_NOWARNING | HTML_PARSE_NONET, optionally HTML_PARSE_NOBLANKS,
    encoding UTF-8): html5 tokenization, libxml2's tree construction with
    implied html/head/body elements and implicit closing of elements, a default
    html 4.0 transitional doctype if none is given.

    Element names are lowercased, there are no namespaces. Character references
    and html named character references (like &nbsp;) are decoded: in html they
    are character references, not declared entities. Raw text (script, style...)
    is stored as cdata nodes, like libxml2.

    Html parsing never fails, errors are reported through the callback in the
    settings and the parser recovers. There is no global state.
*/

#ifndef BUILDING_DIST_XMQ
#include"xml_dom.h"
#include"xml_parser.h"
#endif

#include<stdbool.h>
#include<stddef.h>

typedef struct
{
    /** Name used in messages, eg the file name. NULL gives "noname.html". */
    const char *source_name;
    /** Drop ignorable blank text nodes (libxml2 HTML_PARSE_NOBLANKS heuristic). */
    bool no_blanks;
    /** Maximum length in bytes of an attribute value, comment or doctype literal (10000000). */
    size_t max_text_length;
    /** Receives recoverable errors, may be NULL. */
    XmlParseMessageCallback message_callback;
    void *message_user_data;
} XmlHtmlParseSettings;

void xml_html_parse_settings_default(XmlHtmlParseSettings *settings);

/** Parse html (UTF-8; like libxml2 a bom is skipped if the input is at least four bytes, a lone
    bom is the character U+FEFF). Always returns a dom (it may lack a root element). */
XmlDom *xml_html_parse_buffer(const char *start, const char *stop, const XmlHtmlParseSettings *settings);

#ifndef XMQ_NO_HTML
#define XML_HTML_PARSER_MODULE
#endif

// PART H XML_HTML_SAVE ////////////////////////////////////////

/*
    Html serializer for the native dom (xml_dom.h). Any dom can be written as
    html, whether it was read by the html parser, the xml parser or built by
    xmq: there is only one dom.

    The output is byte compatible with libxml2 htmlDocContentDumpFormatOutput
    and htmlNodeDumpFormatOutput (the libxmq fork in 3rdparty/libxml2), as
    called by libxmq: utf8 output, no meta charset handling.
*/

#ifndef BUILDING_DIST_XMQ
#include"xml_dom.h"
#include"membuffer.h"
#endif

#include<stdbool.h>
#include<stddef.h>

/** Serialize the document as html (doctype first, then the content). */
void xml_html_save_doc_to(MemBuffer *mb, XmlDom *dom, bool format);
char *xml_html_save_doc(XmlDom *dom, bool format, size_t *out_len);

/** Serialize a node and its subtree as html. */
void xml_html_save_node_to(MemBuffer *mb, const XMQNode *node, bool format);
char *xml_html_save_node(const XMQNode *node, bool format, size_t *out_len);

/** Create or update the meta tags with the encoding in the head (libxml2 htmlSetMetaEncoding).
    Returns 0, or 1 if there is no html/head. */
int xml_html_set_meta_encoding(XmlDom *dom, const char *encoding);

#ifndef XMQ_NO_HTML
#define XML_HTML_SAVE_MODULE
#endif

// PART H XML_XPATH ////////////////////////////////////////

/*
    XPath 1.0 on the native dom (xml_dom.h), with the same results as libxml2
    xmlXPathEval (the libxmq fork in 3rdparty/libxml2): the same core function
    library, number formatting, node set ordering and the same streaming
    evaluation of simple paths.

    Entity references are never expanded (see xml_parser.h), so unlike libxml2
    the replacement text of an entity is not visible to xpath: entity reference
    nodes are not selected by any node test and contribute nothing to string values.

    There is no global state: namespaces and options are given per call.
*/

#ifndef BUILDING_DIST_XMQ
#include"xml_dom.h"
#endif

#include<stdbool.h>
#include<stddef.h>

typedef enum
{
    XML_XPATH_NODESET = 1,
    XML_XPATH_BOOLEAN = 2,
    XML_XPATH_NUMBER = 3,
    XML_XPATH_STRING = 4,
} XmlXPathType;

/** Error codes, the same numbers as libxml2 xmlXPathError. */
typedef enum
{
    XML_XPATH_ERR_OK = 0,
    XML_XPATH_ERR_NUMBER = 1,
    XML_XPATH_ERR_UNFINISHED_LITERAL = 2,
    XML_XPATH_ERR_START_LITERAL = 3,
    XML_XPATH_ERR_VARIABLE_REF = 4,
    XML_XPATH_ERR_UNDEF_VARIABLE = 5,
    XML_XPATH_ERR_INVALID_PREDICATE = 6,
    XML_XPATH_ERR_EXPR = 7,
    XML_XPATH_ERR_UNCLOSED = 8,
    XML_XPATH_ERR_UNKNOWN_FUNC = 9,
    XML_XPATH_ERR_INVALID_OPERAND = 10,
    XML_XPATH_ERR_INVALID_TYPE = 11,
    XML_XPATH_ERR_INVALID_ARITY = 12,
    XML_XPATH_ERR_INVALID_CTXT_SIZE = 13,
    XML_XPATH_ERR_INVALID_CTXT_POSITION = 14,
    XML_XPATH_ERR_MEMORY = 15,
    XML_XPATH_ERR_UNDEF_PREFIX = 19,
    XML_XPATH_ERR_FORBID_VARIABLE = 24,
    XML_XPATH_ERR_RECURSION_LIMIT_EXCEEDED = 26,
} XmlXPathErrorCode;

typedef struct
{
    const char *prefix;
    const char *uri;
} XmlXPathNamespace;

typedef struct
{
    /** Prefixes that may be used in expressions (the xml prefix is always known). */
    const XmlXPathNamespace *namespaces;
    size_t num_namespaces;
    /** id() also finds id attributes (and name on a), like libxml2 for html documents. */
    bool html_ids;
    /** Maximum nesting of the expression (libxml2 XPATH_MAX_RECURSION_DEPTH). */
    size_t max_depth;
    /** The context node given to xml_xpath_eval only selects the document, there is no context node
        (like a fresh libxml2 xmlXPathNewContext): relative paths select nothing. */
    bool no_context_node;
    /** Variable references are compile errors (libxml2 XML_XPATH_NOVAR, xslt patterns). */
    bool no_variables;
} XmlXPathSettings;

typedef struct
{
    XmlXPathErrorCode code;
    /** Static libxml2 error message, eg "Invalid expression". */
    const char *message;
    /** Byte offset in the expression where a compile error was found. */
    size_t offset;
    /** The error happened while evaluating a compiled expression (libxml2 has no expression
        context for such errors). */
    bool evaluating;
    /** An extension function failed without a message (like setting ctxt->error in libxml2),
        nothing should be reported. */
    bool quiet;
    /** The message with details (libxml2 xmlXPathErrFmt), eg "Unregistered function: f", or "". */
    char detail[256];
} XmlXPathError;

struct XmlXPathResult;
typedef struct XmlXPathResult XmlXPathResult;

void xml_xpath_settings_default(XmlXPathSettings *settings);

/** Evaluate expr with context as the context node. Returns NULL on error, then error (if not NULL)
    is filled in. settings may be NULL for the defaults. */
XmlXPathResult *xml_xpath_eval(const char *expr, XMQNode *context, const XmlXPathSettings *settings, XmlXPathError *error);

XmlXPathType xml_xpath_result_type(const XmlXPathResult *r);
/** The number of nodes for a node set, 0 for other results. The nodes are in document order. */
size_t xml_xpath_result_size(const XmlXPathResult *r);
XMQNode *xml_xpath_result_node(const XmlXPathResult *r, size_t i);
bool xml_xpath_result_boolean(const XmlXPathResult *r);
double xml_xpath_result_number(const XmlXPathResult *r);
/** The string result (for a string result), NULL otherwise. */
const char *xml_xpath_result_string(const XmlXPathResult *r);
/** Frees the result, including any namespace nodes it contains. */
void xml_xpath_result_free(XmlXPathResult *r);

// Values created by the caller, eg variable values and extension function results.
XmlXPathResult *xml_xpath_result_new_string(const char *s);
XmlXPathResult *xml_xpath_result_new_number(double d);
XmlXPathResult *xml_xpath_result_new_boolean(bool b);
/** An empty node set, add nodes with xml_xpath_result_add_node. */
XmlXPathResult *xml_xpath_result_new_nodeset(void);
/** Append a node to a node set (no check for duplicates or order, see xml_xpath_context_sort). */
void xml_xpath_result_add_node(XmlXPathResult *r, XMQNode *n);
/** Mark a node set as a result tree fragment (libxml2 XPATH_XSLT_TREE, the value of an xslt
    variable with content): it behaves like a node set except that path steps, predicates
    and unions on it are type errors. Copies keep the mark. */
void xml_xpath_result_set_tree(XmlXPathResult *r, bool tree);
bool xml_xpath_result_is_tree(const XmlXPathResult *r);
/** A copy, namespace nodes owned by r are copied too. */
XmlXPathResult *xml_xpath_result_copy(const XmlXPathResult *r);
/** The XPath string(), number() and boolean() of a value. The string is malloced. */
char *xml_xpath_result_to_string(const XmlXPathResult *r);
double xml_xpath_result_to_number(const XmlXPathResult *r);
bool xml_xpath_result_to_boolean(const XmlXPathResult *r);

// Compiled expressions and evaluation contexts, used by xslt //////////////

/** A compiled expression, evaluated any number of times with xml_xpath_eval_comp. */
struct XmlXPathComp;
typedef struct XmlXPathComp XmlXPathComp;

/**
    An evaluation context: the document order index and the id tables of the trees
    seen so far are kept between evaluations, and variables and extension functions
    are resolved through callbacks. The trees must not change while the context
    knows them: call xml_xpath_context_forget before a tree is changed or freed.
*/
struct XmlXPathContext;
typedef struct XmlXPathContext XmlXPathContext;

/** Return the value of the variable (borrowed, it must live until the evaluation
    ends), or NULL if it is not defined. ns_uri is NULL for an unprefixed name. */
typedef const XmlXPathResult *(*XmlXPathVariableLookup)(void *user_data, const char *name, const char *ns_uri);

/** An extension function. Returns a new value, or NULL after calling
    xml_xpath_context_set_error. The arguments are owned by the caller. */
typedef XmlXPathResult *(*XmlXPathFunction)(XmlXPathContext *ctx, void *func_data, XmlXPathResult **args, size_t nargs);

/** Find an extension function (called for names that are not XPath core functions),
    returns NULL if there is none. *func_data is passed to the function. */
typedef XmlXPathFunction (*XmlXPathFunctionLookup)(void *user_data, const char *name, const char *ns_uri, void **func_data);

XmlXPathComp *xml_xpath_compile(const char *expr, const XmlXPathSettings *settings, XmlXPathError *error);
void xml_xpath_comp_free(XmlXPathComp *comp);
/** The expression as given to xml_xpath_compile. */
const char *xml_xpath_comp_source(const XmlXPathComp *comp);

XmlXPathContext *xml_xpath_context_new(void);
void xml_xpath_context_free(XmlXPathContext *ctx);
void xml_xpath_context_set_variable_lookup(XmlXPathContext *ctx, XmlXPathVariableLookup lookup, void *user_data);
void xml_xpath_context_set_function_lookup(XmlXPathContext *ctx, XmlXPathFunctionLookup lookup, void *user_data);
/** Drop what the context knows about the tree with this root, before it is changed or freed. */
void xml_xpath_context_forget(XmlXPathContext *ctx, XMQNode *root);

/**
    Evaluate a compiled expression with node as context node, position and size
    as the context position and size (-1 if unknown, then position() and last()
    are errors). Returns NULL on an error, then error (if not NULL) is filled in.
*/
XmlXPathResult *xml_xpath_eval_comp(XmlXPathContext *ctx, const XmlXPathComp *comp, XMQNode *node,
                                    long position, long size, XmlXPathError *error);

/** Sort a node set into document order and remove duplicates, like the result of a union. */
void xml_xpath_context_sort(XmlXPathContext *ctx, XmlXPathResult *r);

// For extension functions, during an evaluation.
XMQNode *xml_xpath_context_node(const XmlXPathContext *ctx);
long xml_xpath_context_position(const XmlXPathContext *ctx);
long xml_xpath_context_size(const XmlXPathContext *ctx);
/** The namespace uri of a prefix in the namespaces of the expression being evaluated, or NULL. */
const char *xml_xpath_context_lookup_namespace(const XmlXPathContext *ctx, const char *prefix);
/** The element with this id (like id() and libxml2 xmlGetID) in the document of node, or NULL. */
XMQNode *xml_xpath_context_get_id(XmlXPathContext *ctx, XMQNode *node, const char *id);
/** Make the current extension function fail with this error. */
void xml_xpath_context_set_error(XmlXPathContext *ctx, XmlXPathErrorCode code);
/** Make the current extension function fail with this error without a message (libxml2 functions
    that set ctxt->error directly). */
void xml_xpath_context_set_error_quiet(XmlXPathContext *ctx, XmlXPathErrorCode code);

/** Format a number like xpath string(), eg 1, 0.5, NaN, Infinity. Malloced. */
char *xml_xpath_format_number(double d);
/** Convert a string to a number like xpath number(). */
double xml_xpath_string_to_number(const char *s);

#define XML_XPATH_MODULE

// PART H XML_URI ////////////////////////////////////////

/* URI references (RFC 3986), parsing, saving and resolving against a base,
   a port of libxml2 uri.c. Used to resolve xml:base, xsl:import, xsl:include
   and document() the way libxml2 xmlBuildURI does. */

#include<stddef.h>

/** A parsed URI reference (libxml2 xmlURI). */
typedef struct XmlURI
{
    char *scheme;
    char *opaque;
    char *authority;
    char *server;
    char *user;
    int port;
    char *path;
    char *query;
    char *fragment;
    int cleanup;
    char *query_raw;
} XmlURI;

XmlURI *xml_uri_create(void);
/** Parse a URI reference, returns 0 or an error code (-1 for out of memory). */
int xml_uri_parse_safe(const char *str, XmlURI **uri_out);
XmlURI *xml_uri_parse(const char *str);
int xml_uri_parse_reference(XmlURI *uri, const char *str);
XmlURI *xml_uri_parse_raw(const char *str, int raw);
/** The uri as an escaped string, malloced. */
char *xml_uri_save(XmlURI *uri);
void xml_uri_free(XmlURI *uri);
int xml_uri_normalize_uri_path(char *path);
/** Unescape %XX sequences, len -1 for the whole string, target NULL to malloc. */
char *xml_uri_unescape_string(const char *str, int len, char *target);
/** Resolve uri against base (libxml2 xmlBuildURISafe): returns 0 and sets *out, or an error code
    (the uri or base are invalid) or -1 for out of memory. */
int xml_uri_build_safe(const char *uri, const char *base, char **out);
/** Escape str to hex except unreserved characters, "@" and those in list (libxml2 xmlURIEscapeStr). */
char *xml_uri_escape_str(const char *str, const char *list);
/** Like xml_uri_build_safe, NULL on errors (libxml2 xmlBuildURI). */
char *xml_uri_build(const char *uri, const char *base);

#define XML_URI_MODULE

