// The maximum depth of nested groups ( ( ( ... ) ) ) in an ixml grammar.
#define IXML_MAX_GROUP_DEPTH 1000

/** Stop reading the grammar with an ixml grammar error, eg "S03 the rule S is defined more than once". */
static void ixml_grammar_error(XMQParseState *state, const char *format, ...)
{
    static char buf[1024];
    va_list args;
    va_start(args, format);
    vsnprintf(buf, sizeof(buf), format, args);
    va_end(args);
    state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
    state->error_info = buf;
    longjmp(state->error_handler, 1);
}

/** S07 a code point above #10FFFF, S08 a surrogate or a noncharacter (#FDD0-#FDEF, #xFFFE, #xFFFF). */
static void check_ixml_codepoint(XMQParseState *state, int64_t cp)
{
    if (cp > 0x10FFFF) ixml_grammar_error(state, "S07 the hex character is beyond #10ffff");
    if (cp >= 0xD800 && cp <= 0xDFFF) ixml_grammar_error(state, "S08 the hex character #%llx is a surrogate", (long long)cp);
    if ((cp >= 0xFDD0 && cp <= 0xFDEF) || (cp & 0xFFFE) == 0xFFFE)
    {
        ixml_grammar_error(state, "S08 the hex character #%llx is not a character", (long long)cp);
    }
}

bool is_ixml_eob(XMQParseState *state)
{
    return state->i >= state->buffer_stop || *(state->i) == 0;
}

bool is_ixml_alias_start(XMQParseState *state)
{
    return *(state->i) == '>';
}

bool is_ixml_alt_start(XMQParseState *state)
{
    char c = *(state->i);
    return
        c == '+' || // Insertion +"hej" or +#a
        c == '!' || // Not lookahead !"hejsan" ![L]
        c == '#' || // encoded literal
        c == '(' || // Group ( "svej" | "hojt" )
        c == '"' || // "string"
        c == '\'' || // 'string'
        c == '[' || // Charset
        c == '~' || // Negative charset
        is_ixml_mark_char(c) || // @^-
        is_ixml_name_start(state);
}

bool is_ixml_alt_end(char c)
{
    return
        c == ';' || // rule : "a", "b" ; "c", "d" .
        c == '|'; // rule : "a", "b" | "c", "d" .
}

bool is_ixml_charset_start(XMQParseState *state)
{
    const char *i = state->i;

    skip_tmark(&i);

    if (*i == '~') i++;
    while (is_ixml_whitespace_char(*i)) i++;

    if (*i == '[') return true;

    return false;
}

int is_ixml_code_start(XMQParseState *state)
{
    char a = *(state->i);
    char b = *(state->i+1);
    bool capital = (a >= 'A' && a <= 'Z');
    if (!capital) return 0;
    // Most unicode category classes (codes) are two characters Nd, Zs, Lu etc.
    // Some aggregated classes are a single uppercase L,N
    // A single silly is LC.
    bool letter = ((b >= 'a' && b <= 'z') || b == 'C');
    if (!letter) return 1;
    return 2;
}

bool is_ixml_comment_start(XMQParseState *state)
{
    return *(state->i) == '{';
}

bool is_ixml_encoded_start(XMQParseState *state)
{
    // -encoded: (tmark, s)?, -"#", hex, s.

    const char *i = state->i;
    skip_tmark(&i);

    char c = *i;
    if (c == '#') return true;
    return false;
}

bool is_ixml_factor_start(XMQParseState *state)
{
    return
        is_ixml_terminal_start(state) ||
        is_ixml_nonterminal_start(state) ||
        is_ixml_insertion_start(state) ||
        is_ixml_not_start(state) ||
        is_ixml_group_start(state);
}

bool is_ixml_group_start(XMQParseState *state)
{
    return *(state->i) == '(';
}

bool is_ixml_group_end(XMQParseState *state)
{
    return *(state->i) == ')';
}

bool is_ixml_insertion_start(XMQParseState *state)
{
    return *(state->i) == '+';
}

bool is_ixml_not_start(XMQParseState *state)
{
    return *(state->i) == '!';
}

bool is_ixml_hex_char(char c)
{
    return
        (c >= 'A' && c <= 'F') ||
        (c >= 'a' && c <= 'f') ||
        (c >= '0' && c <= '9');
}

bool is_ixml_hex_start(XMQParseState *state)
{
    return is_ixml_hex_char(*(state->i));
}

bool is_ixml_literal_start(XMQParseState *state)
{
    const char *i = state->i;
    skip_tmark(&i);

    char c = *i;
    return c == '"' || c == '\'' || c == '#';
}

bool is_ixml_mark_char(char c)
{
    return
        c == '@' || // Add as attribute.
        c == '^' || // Add as element (default but can be used to override attribute).
        c == '-';   // Do not generate node.
}

// ixml spec (see 3rdparty/ixml/tests/reference/ixml.ixml):
//   -namestart:    ["_"; L].
//   -namefollower: namestart; ["-." + U+00B7 + U+203F + U+2040; Nd; Mn].
// A codepoint is a name-follower if it is a namestart char ("_" or a letter,
// L), one of the explicit follower chars (hyphen "-" U+002D, period "." U+002E,
// middle dot U+00B7, undertie U+203F, glon U+2040), a decimal digit (Nd), or a
// nonspacing mark (Mn).
static bool is_ixml_name_follower_codepoint(int cp)
{
    if (cp == '_') return true; // namestart

    // Explicit namefollower chars.
    if (cp == 0x002D || cp == 0x002E ||
        cp == 0x00B7 || cp == 0x203F || cp == 0x2040)
    {
        return true;
    }

    // Namestart (L, any letter), Nd (decimal number) and Mn (nonspacing mark).
    // The combined "L" category may be empty in this build, so also check the
    // individual letter categories.
    const char *cats[] = {"L", "Lu", "Ll", "Lt", "Lm", "Lo", "Nd", "Mn"};
    for (size_t n = 0; n < sizeof(cats)/sizeof(cats[0]); ++n)
    {
        UnicodeCategoryRange *cat = NULL;
        size_t cat_len = 0;
        if (unicode_get_category_part(cats[n], &cat, &cat_len) &&
            category_has_code(cp, cat, cat_len))
        {
            return true;
        }
    }

    return false;
}

// A UTF-8 aware check: true if the character at state->i is a name follower.
// It inspects the whole (possibly multi-byte) UTF-8 sequence so that non-ASCII
// followers (letters, Nd, Mn and the special punctuation above) are accepted.
//
// The period ("." U+002E) needs a lookahead, because it is ambiguous with the
// rule/alternative terminator. A name may *contain* a period, but a *trailing*
// period always terminates the current rule rather than ending the name. So a
// period only counts as a name follower when the name continues immediately
// after it (e.g. "6.0", "foo.bar", the following character being another name
// follower). If it is the last character of the token (followed by whitespace,
// end-of-buffer, a structural separator such as "," ";" "|", or the start of
// the next "name =" rule) it is the rule terminator and is NOT consumed into
// the name.
bool is_ixml_name_follower(XMQParseState *state)
{
    if (!state) return false;
    if (state->i < state->buffer_start || state->i >= state->buffer_stop) return false;

    int cp = 0;
    size_t len = 0;
    if (!decode_utf8(state->i, state->buffer_stop, &cp, &len)) return false;

    if (cp == 0x002E)
    {
        // Period: a follower only if the name continues immediately after it.
        const char *next = state->i + len;
        if (next >= state->buffer_stop) return false;
        int cp2 = 0;
        size_t len2 = 0;
        if (!decode_utf8(next, state->buffer_stop, &cp2, &len2)) return false;
        (void)len2;
        return is_ixml_name_follower_codepoint(cp2);
    }

    return is_ixml_name_follower_codepoint(cp);
}

// -namestart: ["_"; L]. Like the followers, a letter can be any Unicode letter.
static bool is_ixml_name_start_codepoint(int cp)
{
    if (cp == '_') return true;
    const char *cats[] = {"L", "Lu", "Ll", "Lt", "Lm", "Lo"};
    for (size_t n = 0; n < sizeof(cats)/sizeof(cats[0]); ++n)
    {
        UnicodeCategoryRange *cat = NULL;
        size_t cat_len = 0;
        if (unicode_get_category_part(cats[n], &cat, &cat_len) &&
            category_has_code(cp, cat, cat_len))
        {
            return true;
        }
    }
    return false;
}

/** True if a name starts at state->i, the whole (possibly multi-byte) UTF-8 character is checked. */
bool is_ixml_name_start(XMQParseState *state)
{
    if (state->i < state->buffer_start || state->i >= state->buffer_stop) return false;
    int cp = 0;
    size_t len = 0;
    if (!decode_utf8(state->i, state->buffer_stop, &cp, &len)) return false;
    return is_ixml_name_start_codepoint(cp);
}

bool is_ixml_naming_start(XMQParseState *state)
{
    return is_ixml_mark_char(*(state->i)) || is_ixml_name_start(state);
}

bool is_ixml_nonterminal_start(XMQParseState *state)
{
    return
        is_ixml_naming_start(state);
}

bool is_ixml_prolog_start(XMQParseState *state)
{
    // prolog: "ixml", RS, "version", RS, ... where RS is whitespace or comments.
    // A rule can also be named ixml, eg ixml: s, rule++s, s. so "version" must follow.
    const char *j = state->i;
    const char *stop = state->buffer_stop;
    if (stop - j < 4 || strncmp(j, "ixml", 4)) return false;
    j += 4;
    if (j >= stop || !is_ixml_whitespace_char(*j)) return false;
    skip_whitespace(&j);
    if (stop - j < 8 || strncmp(j, "version", 7)) return false;
    return is_ixml_whitespace_char(*(j+7));
}

bool is_ixml_range_start(XMQParseState *state)
{
    // -range: from, s, -"-", s, to.
    // @from: character.
    // @to: character.
    // -character: -'"', dchar, -'"';
    //             -"'", schar, -"'";
    //             "#", hex.

    const char *j = state->i;
    if (is_ixml_string_start(state))
    {
        skip_string(&j);
        skip_whitespace(&j);
        if (*j == '-') return true;
        return false;
    }
    else if (is_ixml_encoded_start(state))
    {
        skip_encoded(&j);
        skip_whitespace(&j);
        if (*j == '-') return true;
        return false;
    }

    return false;
}

bool is_ixml_string_char(char c)
{
    // Detect "howdy "" there" or 'howdy '' there'
    return c == '"' || c== '\'';
}

bool is_ixml_string_start(XMQParseState *state)
{
    return is_ixml_string_char(*(state->i));
}

bool is_ixml_term_start(XMQParseState *state)
{
    return is_ixml_factor_start(state);
}

bool is_ixml_quote_start(char c)
{
    return c == '"' || c == '\'';
}

bool is_ixml_quoted_start(XMQParseState *state)
{
    //  -quoted: (tmark, s)?, string, s.

    const char *i = state->i;
    skip_tmark(&i);
    char c = *i;
    return c == '"' || c  == '\'';
}

bool is_ixml_rule_start(XMQParseState *state)
{
    //  rule: (mark, s)?, name,
    if (is_ixml_naming_start(state)) return true;

    return false;
}

bool is_ixml_rule_end(char c)
{
    return c == '.'; // rule : "a", "b" ; "c", "d" .
}

bool is_ixml_terminal_start(XMQParseState *state)
{
    return
        is_ixml_encoded_start(state) ||
        is_ixml_literal_start(state) ||
        is_ixml_charset_start(state);
}

bool is_ixml_tmark_char(char c)
{
    return
        c == '^' || // Add as element (default but can be used to override attribute).
        c == '-';   // Do not generate node.
}

bool is_ixml_tmark_start(XMQParseState *state)
{
    return is_ixml_tmark_char(*(state->i));
}

bool is_ixml_whitespace_char(char c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '{' || c == '}';
}

bool is_ixml_whitespace_start(XMQParseState *state)
{
    return is_ixml_whitespace_char(*(state->i));
}

/////////////////////////////////////////////////////////////////////////////

void parse_ixml(XMQParseState *state)
{
    XMQNode *root = xml_node_new_element(state->doq->dom_, "ixml", NULL);
    state->element_last = root;
    xml_dom_set_root_element(state->doq->dom_, root);
    state->doq->root_ = root;
    stack_push(state->element_stack, state->element_last);

    // ixml: s, prolog?, rule++RS, s.
    parse_ixml_whitespace(state);

    if (is_ixml_prolog_start(state))
    {
        parse_ixml_prolog(state);
        parse_ixml_whitespace(state);
    }

    if (!is_ixml_rule_start(state))
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected rule here";
        longjmp(state->error_handler, 1);
    }

    while (is_ixml_rule_start(state))
    {
        parse_ixml_rule(state);
    }

    parse_ixml_whitespace(state);
}

void parse_ixml_alias(XMQParseState *state, const char **alias_start, const char **alias_stop)
{
    IXML_STEP(alias, state);

    ASSERT(is_ixml_alias_start(state));
    EAT(alias_start, 1);

    parse_ixml_whitespace(state);

    parse_ixml_name(state, alias_start, alias_stop);

    parse_ixml_whitespace(state);

    IXML_DONE(alias, state);
}

void parse_ixml_alt(XMQParseState *state)
{
    // alt: term**(-",", s).
    IXML_STEP(alt, state);

    for (;;)
    {
        if (!is_ixml_alt_start(state))
        {
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR; // TODO
            state->error_info = "expected term here";
            longjmp(state->error_handler, 1);
        }
        parse_ixml_term(state);

        parse_ixml_whitespace(state);

        char c = *(state->i);
        if (is_ixml_alt_end(c) ||
            is_ixml_group_end(state) ||
            is_ixml_rule_end(c)) break;

        if (c != ',')
        {
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
            state->error_info = "expected , or . here";
            longjmp(state->error_handler, 1);
        }
        EAT(comma, 1);

        parse_ixml_whitespace(state);
    }


    IXML_DONE(alt, state);
}

void parse_ixml_alts(XMQParseState *state)
{
    IXML_STEP(alts, state);

    // alts: alt++(-[";|"], s).
    for (;;)
    {
        parse_ixml_whitespace(state);

        if (is_ixml_eob(state) ||
            is_ixml_rule_end(*(state->i)) ||
            is_ixml_group_end(state)) break;

        char c = *(state->i);
        // An alternative can be empty, eg A: ; B. or A: 'a'; .
        if (c != '|' && c != ';')
        {
            if (!is_ixml_alt_start(state))
            {
                state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR; // TODO
                state->error_info = "expected alt here";
                longjmp(state->error_handler, 1);
            }
            parse_ixml_alt(state);

            parse_ixml_whitespace(state);
        }

        c = *(state->i);
        if (is_ixml_rule_end(c) || is_ixml_group_end(state)) break;
        if (c != '|' && c != ';')
        {
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
            state->error_info = "expected ; or | here";
            longjmp(state->error_handler, 1);
        }
        EAT(choice, 1);

        // The yaep grammar performs | by having mutiple rule entries
        // with the same name. We reached an alternative version of this
        // rule, create a new rule with the same name.
        parse_ixml_whitespace(state);
        IXMLNonTerminal *name = state->ixml_rule->rule_name;
        char mark = state->ixml_rule->mark;
        // The cost rule =< ... applies to all alternatives of the rule.
        int cost = state->ixml_rule->cost;
        state->ixml_rule = new_ixml_rule();
        state->ixml_rule->cost = cost;
        state->ixml_rule->rule_name->name = strdup(name->name);
        if (name->alias)
        {
            state->ixml_rule->rule_name->alias = strdup(name->alias);
        }
        state->ixml_rule->mark = mark;
        vector_push_back(state->ixml_rules, state->ixml_rule);
    }

    IXML_DONE(alts, state);
}

IXMLNonTerminal *parse_ixml_charset(XMQParseState *state, int *out_tmark)
{
    IXML_STEP(charset, state);
    ASSERT(is_ixml_charset_start(state));

    char tmark = 0;
    if (is_ixml_tmark_char(*(state->i)))
    {
        tmark = *(state->i);
        EAT(tmark, 1);
        parse_ixml_whitespace(state);
    }

    char category[3];
    category[0] = 0;
    bool exclude = false;
    if (*(state->i) == '~')
    {
        exclude = true;
        EAT(negate, 1);
        parse_ixml_whitespace(state);
    }

    ASSERT(*(state->i) == '[');

    EAT(left_bracket, 1);
    parse_ixml_whitespace(state);

    state->ixml_charset = new_ixml_charset(exclude);

    for (;;)
    {
        if (is_ixml_eob(state))
        {
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
            state->error_info = "charset is not closed";
            longjmp(state->error_handler, 1);
        }
        else if (is_ixml_range_start(state))
        {
            parse_ixml_range(state);
            new_ixml_charset_part(state->ixml_charset,
                                  state->ixml_charset_from,
                                  state->ixml_charset_to,
                                  "");
        }
        else if (is_ixml_encoded_start(state))
        {
            parse_ixml_encoded(state, false);
            new_ixml_charset_part(state->ixml_charset,
                                  state->ixml_encoded,
                                  state->ixml_encoded,
                                  "");
        }
        else if (is_ixml_code_start(state))
        {
            // Category can be Lc or just L.
            int n = is_ixml_code_start(state);
            category[0] = *state->i;
            category[1] = 0;
            if (n > 1) category[1] = *(state->i+1);
            category[2] = 0;
            EAT(unicode_category, n);
            const char **check = unicode_lookup_category_parts(category);
            if (!check)
            {
                state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
                state->error_info = "unknown unicode category";
                longjmp(state->error_handler, 1);
            }
            parse_ixml_whitespace(state);
            new_ixml_charset_part(state->ixml_charset,
                                  0,
                                  0,
                                  category);
        }
        else if (is_ixml_string_start(state))
        {
            int *content = NULL;
            parse_ixml_string(state, &content);
            int *i = content;
            while (*i)
            {
                new_ixml_charset_part(state->ixml_charset,
                                      *i,
                                      *i,
                                      "");
                i++;
            }
            free(content);
            parse_ixml_whitespace(state);
        }

        char c = *(state->i);
        if (c == ']') break;
        if (c != ';' && c != '|')
        {
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
            state->error_info = "expected ; or |";
            longjmp(state->error_handler, 1);
        }

        EAT(next_charset_part, 1);
        parse_ixml_whitespace(state);
    }

    EAT(right_bracket, 1);
    IXML_DONE(charset, state);

    char *cs_name = generate_charset_rule_name(state->ixml_charset, tmark);
    IXMLNonTerminal *nt = lookup_yaep_nonterminal_already(state, cs_name);
    if (!nt)
    {
        nt = new_ixml_nonterminal();
        nt->name = cs_name;
        nt->charset = state->ixml_charset;
        add_yaep_nonterminal(state, nt);
    }
    else
    {
        free_ixml_charset(state->ixml_charset);
        state->ixml_charset = NULL;
        free(cs_name);
    }
    *out_tmark = tmark;
    return nt;
}

void parse_ixml_comment(XMQParseState *state)
{
    IXML_STEP(comment, state);
    assert (*(state->i) == '{');

    EAT(comment_start, 1);

    // Comments nest, count the depth instead of recursing, a deeply nested
    // comment must not exhaust the stack.
    size_t depth = 1;
    for (;;)
    {
        if (is_ixml_eob(state))
        {
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
            state->error_info = "comment is not closed";
            longjmp(state->error_handler, 1);
        }
        char c = *(state->i);
        if (c == '{') depth++;
        else if (c == '}' && --depth == 0) break;
        EAT(comment_inside, 1);
    }
    EAT(comment_stop, 1);

    IXML_DONE(comment, state);
}

void parse_ixml_encoded(XMQParseState *state, bool add_terminal)
{
    IXML_STEP(encoded, state);
    ASSERT(is_ixml_encoded_start(state));

    int tmark = 0;
    if (is_ixml_tmark_start(state))
    {
        tmark = *(state->i);
        EAT(encoded_tmark, 1);
    }

    parse_ixml_whitespace(state);

    char c = *(state->i);
    ASSERT(c == '#');
    EAT(hash, 1);

    if (!is_ixml_hex_start(state))
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected hex after #";
        longjmp(state->error_handler, 1);
    }

    int value;
    parse_ixml_hex(state, &value);
    state->ixml_mark = tmark;
    state->ixml_encoded = value;

    parse_ixml_whitespace(state);

    if (add_terminal)
    {
        char buffer[16];
        snprintf(buffer, 15, "#%x", value);

        add_yaep_tmp_term_terminal(state, strdup(buffer), value);
    }

    IXML_DONE(encoded, state);
}

void parse_ixml_factor(XMQParseState *state)
{
    IXML_STEP(factor, state);
    ASSERT(is_ixml_factor_start(state));

    if (is_ixml_terminal_start(state))
    {
        allocate_yaep_tmp_terminals(state);

        parse_ixml_terminal(state);

        if (has_ixml_tmp_terminals(state))
        {
            if (has_more_than_one_ixml_tmp_terminals(state))
            {
                // Create a group.
                IXMLNonTerminal *nt = new_ixml_nonterminal();
                nt->name = generate_rule_name(state);
                add_yaep_nonterminal(state, nt);
                add_yaep_term_to_rule(state, '-', NULL, nt);
                stack_push(state->ixml_rule_stack, state->ixml_rule);
                state->ixml_rule = new_ixml_rule();
                state->ixml_rule->mark = '-';
                vector_push_back(state->ixml_rules, state->ixml_rule);

                free_ixml_nonterminal(state->ixml_rule->rule_name);
                state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

                // Add the terminals to the inner group/rule.
                add_yaep_tmp_terminals_to_rule(state, state->ixml_rule, state->ixml_mark);

                // Pop back out.
                state->ixml_rule = (IXMLRule*)stack_pop(state->ixml_rule_stack);
            }
            else
            {
                add_yaep_tmp_terminals_to_rule(state, state->ixml_rule, state->ixml_mark);
            }
        }

        free_yaep_tmp_terminals(state);
    }
    else if (is_ixml_nonterminal_start(state))
    {
        state->ixml_nonterminal = new_ixml_nonterminal();

        parse_ixml_term_nonterminal(state);

        add_yaep_nonterminal(state, state->ixml_nonterminal);
        add_yaep_term_to_rule(state, state->ixml_mark, NULL, state->ixml_nonterminal);
    }
    else  if (is_ixml_insertion_start(state))
    {
        parse_ixml_insertion(state);
    }
    else  if (is_ixml_not_start(state))
    {
        parse_ixml_not(state);
    }
    else if (is_ixml_group_start(state))
    {
        parse_ixml_group(state);
    }

    parse_ixml_whitespace(state);

    IXML_DONE(factor, state);
}

void parse_ixml_group(XMQParseState *state)
{
    IXML_STEP(group, state);
    ASSERT(is_ixml_group_start(state));

    // Every nested group recurses through alts, alt, term and factor.
    if (++state->nesting_depth > IXML_MAX_GROUP_DEPTH)
    {
        ixml_grammar_error(state, "groups are nested too deep, more than %d", IXML_MAX_GROUP_DEPTH);
    }

    EAT(left_par, 1);

    parse_ixml_whitespace(state);

    // The group is a generated rule with the alternatives. They may be empty,
    // eg () or (; 'a'), then the group matches the empty input.
    IXMLNonTerminal *nt = new_ixml_nonterminal();
    nt->name = generate_rule_name(state);

    add_yaep_nonterminal(state, nt);
    add_yaep_term_to_rule(state, '-', NULL, nt);

    stack_push(state->ixml_rule_stack, state->ixml_rule);
    state->ixml_rule = new_ixml_rule();
    state->ixml_rule->mark = '-';
    vector_push_back(state->ixml_rules, state->ixml_rule);

    free_ixml_nonterminal(state->ixml_rule->rule_name);
    state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

    parse_ixml_alts(state);

    state->ixml_rule = (IXMLRule*)stack_pop(state->ixml_rule_stack);

    if (*(state->i) != ')')
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected ) to close group";
        longjmp(state->error_handler, 1);
    }
    EAT(right_par, 1);
    state->nesting_depth--;

    parse_ixml_whitespace(state);

    IXML_DONE(factor, state);
}

void parse_ixml_hex(XMQParseState *state, int *value)
{
    IXML_STEP(hex,state);

    // Computed digit by digit, a long hex like #decafbadbadbadbad must not overflow.
    int64_t v = 0;
    while (is_ixml_hex_start(state))
    {
        char c = *(state->i);
        int d = (c >= '0' && c <= '9') ? c-'0' : (c >= 'a' && c <= 'f') ? c-'a'+10 : c-'A'+10;
        if (v <= 0x10FFFF) v = v*16 + d;
        EAT(hex_inside, 1);
    }
    check_ixml_codepoint(state, v);
    *value = (int)v;

    IXML_DONE(hex, state);
}

void parse_ixml_insertion(XMQParseState *state)
{
    IXML_STEP(insertion,state);

    ASSERT(is_ixml_insertion_start(state));

    EAT(insertion_plus, 1);

    parse_ixml_whitespace(state);

    if (is_ixml_string_start(state))
    {
        int *content = NULL;
        parse_ixml_string(state, &content);
        size_t len;
        for (len = 0; content[len]; ++len);
        // If all require 4 bytes of utf8, then this is the max length.
        char *buf = (char*)malloc(len*4 + 1);
        size_t offset = 0;
        for (size_t i = 0; i < len; ++i)
        {
            UTF8Char c;
            size_t l = encode_utf8(content[i], &c);
            strncpy(buf+offset, c.bytes, l);
            offset += l;
        }
        buf[offset] = 0;
        add_insertion_rule(state, buf);
        free(buf);
        free(content);
    }
    else if (is_ixml_encoded_start(state))
    {
        allocate_yaep_tmp_terminals(state);
        parse_ixml_encoded(state, true);
        UTF8Char c;
        encode_utf8(state->ixml_encoded, &c);
        char buf[16];
        snprintf(buf, 16, "#%x", state->ixml_encoded),
        add_insertion_rule(state, buf);
        free_yaep_tmp_terminals_and_content(state);
    }
    else
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected string or encoded character after insertion +";
        longjmp(state->error_handler, 1);
    }

    IXML_DONE(insertion, state);
}

void parse_ixml_not(XMQParseState *state)
{
    IXML_STEP(insertion,state);

    ASSERT(is_ixml_not_start(state));

    EAT(not_bang, 1);

    parse_ixml_whitespace(state);

    if (is_ixml_string_start(state))
    {
        int *content = NULL;
        parse_ixml_string(state, &content);
        size_t len;
        for (len = 0; content[len]; ++len);
        // If all require 4 bytes of utf8, then this is the max length.
        char *buf = (char*)malloc(len*4 + 1);
        size_t offset = 0;
        for (size_t i = 0; i < len; ++i)
        {
            UTF8Char c;
            size_t l = encode_utf8(content[i], &c);
            strncpy(buf+offset, c.bytes, l);
            offset += l;
        }
        buf[offset] = 0;
        add_not_rule_string(state, buf);
        free(buf);
        free(content);
    }
    else if (is_ixml_encoded_start(state))
    {
        allocate_yaep_tmp_terminals(state);
        parse_ixml_encoded(state, true);
        UTF8Char c;
        encode_utf8(state->ixml_encoded, &c);
        add_not_rule_string(state, c.bytes);
        free_yaep_tmp_terminals_and_content(state);
    }
    else if (is_ixml_charset_start(state))
    {
        int tmark;
        IXMLNonTerminal *nt = parse_ixml_charset(state, &tmark);
        add_not_rule_charset(state, nt);
    }
    else if (is_ixml_name_start(state))
    {
        // !name where the rule name matches one character, eg
        // -namechar = ['a'-'z'; '0'-'9'], or alternatives of fixed sequences
        // of characters, eg -kw = 'if', ~[L] | 'else', ~[L].
        // Checked when the grammar is read.
        const char *name_start, *name_stop;
        parse_ixml_name(state, &name_start, &name_stop);
        char *name = strndup(name_start, name_stop-name_start);
        add_not_rule_nonterminal(state, name);
        free(name);
    }
    else
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected string, encoded character, charset or rule name after not !";
        longjmp(state->error_handler, 1);
    }

    IXML_DONE(insertion, state);
}

void parse_ixml_literal(XMQParseState *state)
{
    IXML_STEP(literal,state);

    ASSERT(is_ixml_literal_start(state));

    if (is_ixml_quoted_start(state))
    {
        parse_ixml_quoted(state);
    }
    else
    {
        parse_ixml_encoded(state, true);
    }

    IXML_DONE(literal, state);
}

void parse_ixml_name(XMQParseState *state, const char **name_start, const char **name_stop)
{
    IXML_STEP(name,state);

    assert(is_ixml_name_start(state));
    *name_start = state->i;
    {
        // The first character may be multi-byte, eg ª.
        int cp = 0;
        size_t len = 0;
        decode_utf8(state->i, state->buffer_stop, &cp, &len);
        if (len < 1 || len > 4) len = 1;
        EAT(name_start, len);
    }

    while (is_ixml_name_follower(state))
    {
        // Followers may be multi-byte (letters, Nd, Mn, ...) so eat the whole
        // UTF-8 sequence, not just the first byte.
        int cp = 0;
        size_t len = 0;
        decode_utf8(state->i, state->buffer_stop, &cp, &len);
        if (len < 1 || len > 4) len = 1;
        EAT(name_inside, len);
    }
    *name_stop = state->i;

    IXML_DONE(name, state);
}

void parse_ixml_naming(XMQParseState *state,
                       char *mark,
                       char **name,
                       char **alias)
{
    IXML_STEP(naming,state);

    ASSERT(is_ixml_naming_start(state));

    if (is_ixml_mark_char(*(state->i)))
    {
        *mark = (*(state->i));
        EAT(naming_mark, 1);
    }
    else
    {
        *mark = 0;
    }
    parse_ixml_whitespace(state);

    if (!is_ixml_name_start(state))
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected a name";
        longjmp(state->error_handler, 1);
    }
    const char *name_start, *name_stop;
    parse_ixml_name(state, &name_start, &name_stop);
    *name = strndup(name_start, (name_stop-name_start));

    parse_ixml_whitespace(state);

    if (is_ixml_alias_start(state))
    {
        const char *alias_start, *alias_stop;
        parse_ixml_alias(state, &alias_start, &alias_stop);
        *alias = strndup(alias_start, alias_stop-alias_start);
    }
    else
    {
        *alias = NULL;
    }

    IXML_DONE(naming, state);
}

void parse_ixml_term_nonterminal(XMQParseState *state)
{
    IXML_STEP(nonterminal, state);
    ASSERT(is_ixml_naming_start(state));

    IXMLNonTerminal *nt = state->ixml_nonterminal;
    parse_ixml_naming(state, &state->ixml_mark, &nt->name, &nt->alias);

    IXML_DONE(nonterminal, state);
}

void parse_ixml_prolog(XMQParseState *state)
{
    IXML_STEP(prolog, state);
    // version: -"ixml", RS, -"version", RS, string, s, -'.' .
    // Example: ixml version "1.2.3-gurka" .

    assert(is_ixml_prolog_start(state));
    EAT(prolog_ixml, 4);

    parse_ixml_whitespace(state);

    if (strncmp(state->i, "version", 7))
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected \"version\" ";
        longjmp(state->error_handler, 1);
    }

    EAT(prolog_version, 7);

    if (!is_ixml_whitespace_start(state))
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected whitespace";
        longjmp(state->error_handler, 1);
    }

    parse_ixml_whitespace(state);

    if (!is_ixml_string_start(state))
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected string";
        longjmp(state->error_handler, 1);
    }

    int *content;
    parse_ixml_string(state, &content);
    // The versions implemented, any other gives ixml:state="version-mismatch" on the result.
    bool is_10 = content[0] == '1' && content[1] == '.' && content[2] == '0' && content[3] == 0;
    bool is_11 = content[0] == '1' && content[1] == '.' && content[2] == '1' && content[3] == 0;
    state->ixml_version_mismatch = !is_10 && !is_11;
    free(content);

    parse_ixml_whitespace(state);

    char c = *(state->i);
    if (c != '.')
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "ixml version must end with a dot";
        longjmp(state->error_handler, 1);
    }
    EAT(prolog_stop, 1);

    IXML_DONE(prolog, state);
}

void parse_ixml_range(XMQParseState *state)
{
    IXML_STEP(range, state);
    ASSERT(is_ixml_range_start(state));

    if (is_ixml_string_start(state))
    {
        int *content;
        parse_ixml_string(state, &content);
        bool single = content[0] != 0 && content[1] == 0;
        state->ixml_charset_from = content[0];
        free(content);
        if (!single) ixml_grammar_error(state, "a range must start with a single character");
    }
    else
    {
        parse_ixml_encoded(state, false);
        state->ixml_charset_from = state->ixml_encoded;
    }
    parse_ixml_whitespace(state);

    // This is guaranteed by the is range test in the assert.
    ASSERT(*(state->i) == '-');
    EAT(range_minus, 1);

    parse_ixml_whitespace(state);

    if (is_ixml_string_start(state))
    {
        int *content;
        parse_ixml_string(state, &content);
        bool single = content[0] != 0 && content[1] == 0;
        state->ixml_charset_to = content[0];
        free(content);
        if (!single) ixml_grammar_error(state, "a range must end with a single character");
    }
    else if (is_ixml_encoded_start(state))
    {
        parse_ixml_encoded(state, false);
        state->ixml_charset_to = state->ixml_encoded;
    }
    else
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected range ending with string or hex char";
        longjmp(state->error_handler, 1);
    }
    if (state->ixml_charset_from > state->ixml_charset_to)
    {
        ixml_grammar_error(state, "S09 the range #%x-#%x ends before it starts",
                           state->ixml_charset_from, state->ixml_charset_to);
    }
    parse_ixml_whitespace(state);

    IXML_DONE(range, state);
}

void parse_ixml_quoted(XMQParseState *state)
{
    IXML_STEP(quoted, state);
    // -quoted: (tmark, s)?, string, s.

    ASSERT(is_ixml_quoted_start(state));

    char tmark = 0;
    if (is_ixml_tmark_start(state))
    {
        tmark = *(state->i);
        EAT(quoted_tmark, 1);
        parse_ixml_whitespace(state);
    }

    state->ixml_mark = tmark;

    int *content = NULL;
    parse_ixml_string(state, &content);

    for (int *i = content; *i; ++i)
    {
        char buf[16];
        snprintf(buf, 15, "#%x", *i);
        add_yaep_tmp_term_terminal(state, strdup(buf), *i);
    }
    free(content);

    parse_ixml_whitespace(state);

    IXML_DONE(quoted, state);
}

void parse_ixml_rule(XMQParseState *state)
{
    // rule: naming, -["=:"], s, -alts, -".".
    IXML_STEP(rule, state);
    ASSERT(is_ixml_naming_start(state));

    stack_push(state->ixml_rule_stack, state->ixml_rule);

    state->ixml_rule = new_ixml_rule();
    vector_push_back(state->ixml_rules, state->ixml_rule);

    parse_ixml_naming(state,
                      &state->ixml_rule->mark,
                      &state->ixml_rule->rule_name->name,
                      &state->ixml_rule->rule_name->alias);

    // S03: a nonterminal is defined by one rule (with alternatives). The rules made so
    // far are the earlier rules, their alternatives and generated rules (|1 or a charset).
    for (size_t i = 0; i + 1 < state->ixml_rules->size; ++i)
    {
        IXMLRule *r = (IXMLRule*)vector_element_at(state->ixml_rules, i);
        if (!strcmp(r->rule_name->name, state->ixml_rule->rule_name->name))
        {
            ixml_grammar_error(state, "S03 the rule %s is defined more than once", state->ixml_rule->rule_name->name);
        }
    }

    parse_ixml_whitespace(state);

    char c = *(state->i);
    if (c != '=' && c != ':')
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected equal or colon here";
        longjmp(state->error_handler, 1);
    }
    EAT(rule_equal, 1);
    while (*(state->i) == '<')
    {
        state->ixml_rule->cost++;
        state->i++;
        state->ixml_costs_enabled = true;
    }

    parse_ixml_whitespace(state);

    parse_ixml_alts(state);

    c = *(state->i);
    if (c != '.')
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected dot here";
        longjmp(state->error_handler, 1);
    }
    EAT(rule_stop, 1);

    parse_ixml_whitespace(state);

    state->ixml_rule = (IXMLRule*)stack_pop(state->ixml_rule_stack);

    IXML_DONE(rule, state);
}

void parse_ixml_string(XMQParseState *state, int **content)
{
    IXML_STEP(string, state);

    MemBuffer *buf = new_membuffer();

    ASSERT(is_ixml_string_start(state));

    char q = *(state->i);
    EAT(string_start, 1);

    for (;;)
    {
        if (is_ixml_eob(state))
        {
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
            state->error_info = "string not terminated";
            longjmp(state->error_handler, 1);
        }

        if (*(state->i) == q)
        {
            if (*(state->i+1) == q)
            {
                // A double '' or "" means a single ' or " inside the string.
                EAT(string_quote, 1);
            }
            else
            {
                EAT(string_stop, 1);
                break;
            }
        }

        int uc = 0;
        size_t len = 0;
        bool ok = decode_utf8(state->i, state->buffer_stop, &uc, &len);
        if (!ok)
        {
            fprintf(stderr, "xmq: broken utf8\n");
            exit(1);
        }
        if (uc == '\n' || uc == '\r')
        {
            free_membuffer_and_free_content(buf);
            ixml_grammar_error(state, "S11 a string can not span lines, use #a for a newline");
        }
        membuffer_append_int(buf, uc);
        EAT(string_inside, len);
    }
    if (membuffer_used(buf) == 0)
    {
        free_membuffer_and_free_content(buf);
        ixml_grammar_error(state, "a string can not be empty");
    }
    // Add a zero termination to the integer array.
    membuffer_append_int(buf, 0);

    char *quote = free_membuffer_but_return_trimmed_content(buf);
    *content = (int*)quote;

    IXML_DONE(string, state);
}

void parse_ixml_term(XMQParseState *state)
{
    IXML_STEP(term, state);
    ASSERT(is_ixml_factor_start(state));

    if (is_ixml_factor_start(state))
    {
        parse_ixml_factor(state);
    }
    else
    {
        state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
        state->error_info = "expected factor";
        longjmp(state->error_handler, 1);
    }

    char c = *(state->i);
    if (c == '?')
    {
        EAT(option, 1);
        parse_ixml_whitespace(state);

        make_last_term_optional(state);
    }
    else if (c == '*' || c == '+')
    {
        // Remember the mark for the member.
        if (c == '*')
        {
            EAT(star, 1);
        }
        else
        {
            EAT(plus, 1);
        }

        char cc = *(state->i);
        if (c == cc)
        {
            // We have value++infix
            if (c == '*')
            {
                EAT(star, 1);
            }
            else
            {
                EAT(plus, 1);
            }
            parse_ixml_whitespace(state);

            // infix separator
            parse_ixml_factor(state);

            // We have value++infix value**infix
            if (c == '+') make_last_term_repeat_infix(state);
            else  make_last_term_repeat_zero_infix(state);

        }
        else
        {
            // We have value+ or value*
            if (c == '+') make_last_term_repeat(state);
            else  make_last_term_repeat_zero(state);
        }
        parse_ixml_whitespace(state);
    }
    parse_ixml_whitespace(state);

    IXML_DONE(term, state);
}

void parse_ixml_terminal(XMQParseState *state)
{
    IXML_STEP(terminal, state);
    ASSERT(is_ixml_literal_start(state) || is_ixml_charset_start(state));

    if (is_ixml_literal_start(state))
    {
        parse_ixml_literal(state);
    }
    else
    {
        int tmark;
        IXMLNonTerminal *nt = parse_ixml_charset(state, &tmark);
        add_yaep_term_to_rule(state, tmark, NULL, nt);
    }

    IXML_DONE(terminal, state);
}

void parse_ixml_whitespace(XMQParseState *state)
{
    if (is_ixml_eob(state) || !is_ixml_whitespace_start(state)) return;

    IXML_STEP(ws, state);

    while (state->i < state->buffer_stop && is_ixml_whitespace_start(state))
    {
        if (is_ixml_comment_start(state))
        {
            parse_ixml_comment(state);
        }
        else
        {
            EAT(ws, 1);
        }
    }

    IXML_DONE(ws, state);
}


const char *ixml_to_yaep_read_terminal(YaepParseRun *pr,
                                       YaepGrammar *g,
                                       int *code)
{
    XMQParseState *state = (XMQParseState*)pr->user_data;
    const char *key;
    void *val;
    bool ok = hashmap_next_key_value(state->yaep_i_, &key, &val);

    if (ok)
    {
        IXMLTerminal *t = (IXMLTerminal*)val;
        *code = t->code;
        return t->name;
    }

    return NULL;
}

const char *ixml_to_yaep_read_rule(YaepParseRun *pr,
                                   YaepGrammar *g,
                                   const char ***rhs,
                                   const char **abs_node,
                                   int *cost,
                                   int **transl,
                                   char *mark,
                                   char **marks,
                                   const char ***aliases)
{
    XMQParseState *state = (XMQParseState*)pr->user_data;
    if (state->yaep_j_ >= state->ixml_rules->size) return NULL;
    IXMLRule *rule = (IXMLRule*)vector_element_at(state->ixml_rules, state->yaep_j_);

    // This is a valid rule.
    size_t num_rhs = rule->rhs_terms->size;

    // Add rhs rules as translations.
    if (state->yaep_tmp_rhs_) free(state->yaep_tmp_rhs_);
    state->yaep_tmp_rhs_ = (char**)calloc(num_rhs+1, sizeof(char*));
    if (state->yaep_tmp_marks_) free(state->yaep_tmp_marks_);
    state->yaep_tmp_marks_ = (char*)calloc(num_rhs+1, sizeof(char));
    memset(state->yaep_tmp_marks_, 0, num_rhs+1);
    if (state->yaep_tmp_aliases_) free(state->yaep_tmp_aliases_);
    state->yaep_tmp_aliases_ = (const char**)calloc(num_rhs+1, sizeof(const char*));

    for (size_t i = 0; i < num_rhs; ++i)
    {
        IXMLTerm *term = (IXMLTerm*)vector_element_at(rule->rhs_terms, i);
        state->yaep_tmp_marks_[i] = term->mark;
        if (term->type == IXML_TERMINAL)
        {
            state->yaep_tmp_rhs_[i] = term->t->name;
        }
        else if (term->type == IXML_NON_TERMINAL)
        {
            state->yaep_tmp_rhs_[i] = term->nt->name;
            state->yaep_tmp_aliases_[i] = term->nt->alias;
        }
        else
        {
            fprintf(stderr, "Internal error %d as term type does not exist!\n", term->type);
            assert(false);
        }
    }

    *abs_node = rule->rule_name->name;
    if (rule->rule_name->alias)
    {
        *abs_node = rule->rule_name->alias;
    }

    if (state->yaep_tmp_transl_) free(state->yaep_tmp_transl_);
    state->yaep_tmp_transl_ = (int*)calloc(num_rhs+1, sizeof(char*));
    for (size_t i = 0; i < num_rhs; ++i)
    {
        state->yaep_tmp_transl_[i] = (int)i;
    }
    state->yaep_tmp_transl_[num_rhs] = -1;

    state->yaep_tmp_rhs_[num_rhs] = NULL;
    *rhs = (const char **)state->yaep_tmp_rhs_;
    *marks = state->yaep_tmp_marks_;
    *aliases = state->yaep_tmp_aliases_;
    *transl = state->yaep_tmp_transl_;
    *cost = rule->cost;
    *mark = rule->mark;

    state->yaep_j_++;
    return rule->rule_name->name;
}

bool ixml_build_yaep_grammar(YaepParseRun *pr,
                             YaepGrammar *g,
                             XMQParseState *state,
                             const char *grammar_start,
                             const char *grammar_stop,
                             const char *content_start,
                             const char *content_stop)
{
    if (state->magic_cookie != MAGIC_COOKIE)
    {
        PRINT_ERROR("Parser state not initialized!\n");
        assert(0);
        exit(1);
    }

    pr->user_data = state;
    pr->grammar = g;
    state->ixml_rules = vector_create();
    state->ixml_terminals_map = hashmap_create(256);
    state->ixml_non_terminals_map = hashmap_create(256);
    state->ixml_non_terminals = vector_create();
    state->ixml_rule_stack = stack_create();

    state->buffer_start = grammar_start;
    state->buffer_stop = grammar_stop;
    state->i = grammar_start;
    state->line = 1;
    state->col = 1;
    state->error_nr = XMQ_OK;

    if (state->parse && state->parse->init) state->parse->init(state);

    if (!setjmp(state->error_handler))
    {
        // Parse the IXML grammar.
        parse_ixml(state);
        if (state->i < state->buffer_stop)
        {
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
            state->error_info = "failed to parse whole buffer";
            longjmp(state->error_handler, 1);
        }
        check_not_rule_nonterminals(state);
        check_undefined_nonterminals(state);
    }
    else
    {
        XMQStatus error_nr = state->error_nr;
        generate_state_error_message(state, error_nr, grammar_start, grammar_stop);
        return false;
    }

    if (state->parse && state->parse->done) state->parse->done(state);

    return true;
}

void skip_comment(const char **i)
{
    const char *j = *i;
    ASSERT(*j == '{');
    // Comments nest, count the depth instead of recursing.
    size_t depth = 1;
    for (;;)
    {
        j++;
        if (*j == 0) return;
        if (*j == '{') depth++;
        else if (*j == '}' && --depth == 0) break;
    }
    j++;
    *i = j;
}

void skip_encoded(const char **i)
{
    const char *j = *i;
    if (*j != '#') return;
    j++;
    while (is_ixml_hex_char(*j)) j++;
    *i = j;
}

void skip_mark(const char **i)
{
    const char *j = *i;
    char c = *j;
    if (c == '^' || c == '-' || c == '@') // mark
    {
        j++;
        while (is_ixml_whitespace_char(*j)) j++;
    }
    *i = j;
}

void skip_string(const char **i)
{
    const char *j = *i;
    if (*j == '"') // mark
    {
        j++;
        while (*j != '"')
        {
            if (*j == 0) return; // Ouch string not closed.
            if (*j == '"' && *(j+1) == '"') j++;
            j++;
        }
        // Move past the last "
        j++;
    }
    else
    if (*j == '\'') // mark
    {
        j++;
        while (*j != '\'')
        {
            if (*j == 0) return; // Ouch string not closed.
            if (*j == '\'' && *(j+1) == '\'') j++;
            j++;
        }
        j++;
    }
    *i = j;
}

void skip_tmark(const char **i)
{
    const char *j = *i;
    char c = *j;
    if (c == '^' || c == '-') // tmark
    {
        j++;
        while (is_ixml_whitespace_char(*j)) j++;
    }
    *i = j;
}

void skip_whitespace(const char **i)
{
    const char *j = *i;
    while (is_ixml_whitespace_char(*j))
    {
        if (*j == '{') skip_comment(&j);
        else j++;
    }
    *i = j;
}

void add_yaep_term_to_rule(XMQParseState *state, char mark, IXMLTerminal *t, IXMLNonTerminal *nt)
{
    IXMLTerm *term = (IXMLTerm*)calloc(1, sizeof(IXMLTerm));
    assert( (t || nt) && !(t && nt) );
    term->type = t ? IXML_TERMINAL :  IXML_NON_TERMINAL;
    term->mark = mark;
    term->t = t;
    term->nt = nt;
    vector_push_back(state->ixml_rule->rhs_terms, term);
}

void add_yaep_terminal(XMQParseState *state, IXMLTerminal *terminal)
{
    hashmap_put(state->ixml_terminals_map, terminal->name, terminal);
}

IXMLNonTerminal *lookup_yaep_nonterminal_already(XMQParseState *state, const char *name)
{
    // FIXME. Replace this with a set or map for faster lookup if needed.
    for (size_t i = 0; i < state->ixml_non_terminals->size; ++i)
    {
        IXMLNonTerminal *nt = (IXMLNonTerminal*)vector_element_at(state->ixml_non_terminals, i);
        if (!strcmp(name, nt->name)) return nt;
    }
    return NULL;
}

void add_yaep_nonterminal(XMQParseState *state, IXMLNonTerminal *nt)
{
    hashmap_put(state->ixml_non_terminals_map, nt->name, nt);
    vector_push_back(state->ixml_non_terminals, nt);
}

void add_yaep_tmp_term_terminal(XMQParseState *state, char *name, int code)
{
    IXMLTerminal *t = new_ixml_terminal();
    t->name = name;
    t->code = code;
    vector_push_back(state->ixml_tmp_terminals, t);
}

void add_single_char_rule(XMQParseState *state, IXMLNonTerminal *nt, int uc, char mark, char tmark)
{
    IXMLRule *rule = new_ixml_rule();
    rule->rule_name->name = strdup(nt->name);
    // No need to copy alias here since this rule is used for single characters for charsets.
    rule->mark = mark;
    vector_push_back(state->ixml_rules, rule);
    char buffer[16];
    snprintf(buffer, 15, "#%x", uc);
    allocate_yaep_tmp_terminals(state);
    add_yaep_tmp_term_terminal(state, strdup(buffer), uc);
    state->ixml_rule = rule; // FIXME this is a bit ugly.
    add_yaep_tmp_terminals_to_rule(state, rule, tmark);
    free_yaep_tmp_terminals(state);
}

void add_insertion_rule(XMQParseState *state, const char *content)
{
    // Generate a name like |+.......
    char *name = (char*)malloc(strlen(content)+3);
    name[0] = '|';
    name[1] = '+';
    strcpy(name+2, content);

    IXMLNonTerminal *nt = (IXMLNonTerminal*)hashmap_get(state->ixml_non_terminals_map, name);
    if (!nt)
    {
        IXMLRule *rule = new_ixml_rule();
        rule->rule_name->name = name;
        rule->mark = ' ';
        vector_push_back(state->ixml_rules, rule);

        nt = copy_ixml_nonterminal(rule->rule_name);
        add_yaep_nonterminal(state, nt);
    }
    else
    {
        // This insertion rule has already been added as a non terminal.
        free(name);
    }

    // Add nt to rule.
    add_yaep_term_to_rule(state, 0, NULL, nt);
}

void add_not_rule_string(XMQParseState *state, const char *content)
{
    // Generate a name like |!S.......
    char *name = (char*)malloc(strlen(content)+4);
    name[0] = '|';
    name[1] = '!';
    name[2] = 'S';
    strcpy(name+3, content);

    IXMLNonTerminal *nt = (IXMLNonTerminal*)hashmap_get(state->ixml_non_terminals_map, name);
    if (nt) {
        // This not rule has already been recorded. Do not create it again,
        // but we must still add the existing not rule to the current rule.
        free(name);
        add_yaep_term_to_rule(state, 0, NULL, nt);
        return;
    }

    IXMLRule *rule = new_ixml_rule();
    rule->rule_name->name = name;
    rule->mark = ' ';
    vector_push_back(state->ixml_rules, rule);

    nt = copy_ixml_nonterminal(rule->rule_name);
    add_yaep_nonterminal(state, nt);
    add_yaep_term_to_rule(state, 0, NULL, nt);
    hashmap_put(state->ixml_non_terminals_map, name, nt);
}

void add_not_rule_charset(XMQParseState *state, IXMLNonTerminal *cs)
{
    // Generate a name like |![...]
    char *name = (char*)malloc(strlen(cs->name)+3);
    name[0] = '|';
    name[1] = '!';
    strcpy(name+2, cs->name);

    IXMLNonTerminal *nt = (IXMLNonTerminal*)hashmap_get(state->ixml_non_terminals_map, name);
    if (nt) {
        // This not rule has already been recorded. Do not create it again,
        // but we must still add the existing not rule to the current rule.
        free(name);
        add_yaep_term_to_rule(state, 0, NULL, nt);
        return;
    }

    IXMLRule *rule = new_ixml_rule();

    rule->rule_name->name = name;
    rule->mark = ' ';
    vector_push_back(state->ixml_rules, rule);

    nt = copy_ixml_nonterminal(rule->rule_name);
    add_yaep_nonterminal(state, nt);
    add_yaep_term_to_rule(state, 0, NULL, nt);
    hashmap_put(state->ixml_non_terminals_map, name, nt);
}

void add_not_rule_nonterminal(XMQParseState *state, const char *rule_name)
{
    // Generate a name like |!Nnamechar
    char *name = (char*)malloc(strlen(rule_name)+4);
    name[0] = '|';
    name[1] = '!';
    name[2] = 'N';
    strcpy(name+3, rule_name);

    IXMLNonTerminal *nt = (IXMLNonTerminal*)hashmap_get(state->ixml_non_terminals_map, name);
    if (nt) {
        free(name);
        add_yaep_term_to_rule(state, 0, NULL, nt);
        return;
    }

    IXMLRule *rule = new_ixml_rule();
    rule->rule_name->name = name;
    rule->mark = ' ';
    vector_push_back(state->ixml_rules, rule);

    nt = copy_ixml_nonterminal(rule->rule_name);
    add_yaep_nonterminal(state, nt);
    add_yaep_term_to_rule(state, 0, NULL, nt);
    hashmap_put(state->ixml_non_terminals_map, name, nt);
}

static int not_rule_kind(XMQParseState *state, const char *name, int depth);

/** A grammar rule or a generated rule |12 (eg a string or a group), but not
    a not |!... or insertion |+... rule. */
static bool is_callable_rule_name(const char *name)
{
    return name[0] != '|' || (name[1] >= '0' && name[1] <= '9');
}

/** Is the term a single character: a character, a charset or a call of a
    rule that matches one character? */
static bool is_single_char_term(XMQParseState *state, IXMLTerm *t, int depth)
{
    if (t->type == IXML_TERMINAL || t->type == IXML_CHARSET) return true;
    if (t->nt && t->nt->charset) return true;
    return t->nt && is_callable_rule_name(t->nt->name) && not_rule_kind(state, t->nt->name, depth+1) == 1;
}

/** What a rule after not ! matches: 1 if exactly one character (every
    alternative a single character, charset or call of such a rule), 2 if a
    single alternative that is a fixed sequence of characters (single
    characters, strings, charsets or calls of rules of kind 1 or 2), 3 if
    several alternatives that are such sequences, 0 otherwise. Kind 3 is only
    allowed directly after the !, since the engine does not backtrack into the
    alternatives of a call inside a sequence. */
static int not_rule_kind(XMQParseState *state, const char *name, int depth)
{
    if (depth > 64) return 0; // A cycle.
    int alts = 0;
    bool all_single = true;
    for (size_t i = 0; i < state->ixml_rules->size; ++i)
    {
        IXMLRule *r = (IXMLRule*)vector_element_at(state->ixml_rules, i);
        if (strcmp(r->rule_name->name, name)) continue;
        alts++;
        size_t n = r->rhs_terms->size;
        if (n == 0) return 0;
        for (size_t t = 0; t < n; ++t)
        {
            IXMLTerm *term = (IXMLTerm*)vector_element_at(r->rhs_terms, t);
            if (is_single_char_term(state, term, depth)) continue;
            if (term->nt && is_callable_rule_name(term->nt->name))
            {
                int k = not_rule_kind(state, term->nt->name, depth+1);
                if (k == 1 || k == 2) { all_single = false; continue; }
            }
            return 0;
        }
        if (n > 1) all_single = false;
    }
    if (alts == 0) return 0;
    if (all_single) return 1;
    return alts == 1 ? 2 : 3;
}

/** Check that every !name refers to a rule that matches one character or
    alternatives of fixed sequences of characters. The engine tests the input against the
    first set of each character of the rule, which is exact only for such rules. */
void check_not_rule_nonterminals(XMQParseState *state)
{
    for (size_t i = 0; i < state->ixml_rules->size; ++i)
    {
        IXMLRule *r = (IXMLRule*)vector_element_at(state->ixml_rules, i);
        const char *n = r->rule_name->name;
        if (n[0] != '|' || n[1] != '!' || n[2] != 'N') continue;
        bool defined = false;
        for (size_t j = 0; j < state->ixml_rules->size && !defined; ++j)
        {
            IXMLRule *d = (IXMLRule*)vector_element_at(state->ixml_rules, j);
            defined = !strcmp(d->rule_name->name, n+3);
        }
        if (!defined || not_rule_kind(state, n+3, 0) == 0)
        {
            static char buf[1024];
            if (!defined) snprintf(buf, sizeof(buf), "the rule %s after not ! is not defined", n+3);
            else snprintf(buf, sizeof(buf),
                          "the rule %s after not ! must match fixed sequences of characters "
                          "(no repetitions, options or empty alternatives)", n+3);
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
            state->error_info = buf;
            longjmp(state->error_handler, 1);
        }
    }
}

/** Every nonterminal used in a rule must be defined by a rule (ixml static error S02). */
void check_undefined_nonterminals(XMQParseState *state)
{
    HashMap *defined = hashmap_create(state->ixml_rules->size * 2 + 16);
    for (size_t i = 0; i < state->ixml_rules->size; ++i)
    {
        IXMLRule *r = (IXMLRule*)vector_element_at(state->ixml_rules, i);
        hashmap_put(defined, r->rule_name->name, r);
    }
    for (size_t i = 0; i < state->ixml_rules->size; ++i)
    {
        IXMLRule *r = (IXMLRule*)vector_element_at(state->ixml_rules, i);
        for (size_t j = 0; j < r->rhs_terms->size; ++j)
        {
            IXMLTerm *term = (IXMLTerm*)vector_element_at(r->rhs_terms, j);
            if (term->type != IXML_NON_TERMINAL || !term->nt || !term->nt->name) continue;
            // Charset rules are generated with the grammar.
            if (term->nt->charset) continue;
            if (hashmap_get(defined, term->nt->name)) continue;
            static char buf[1024];
            snprintf(buf, sizeof(buf), "S02 the rule %s is not defined", term->nt->name);
            hashmap_free(defined);
            state->error_nr = XMQ_ERROR_IXML_SYNTAX_ERROR;
            state->error_info = buf;
            longjmp(state->error_handler, 1);
        }
    }
    hashmap_free(defined);
}

// The ixml text of a grammar in xml form //////////////////////////////////////////////

typedef struct
{
    MemBuffer *mb;
    char *error; // The first error, malloced.
} IXMLFromXml;

static void fx_error(IXMLFromXml *x, const char *format, const char *arg)
{
    if (x->error) return;
    char buf[1024];
    snprintf(buf, sizeof(buf), format, arg ? arg : "");
    x->error = strdup(buf);
}

/** The next element from node (node included), skipping text and comments. */
static XMQNode *fx_element(XMQNode *node)
{
    while (node && xml_node_kind(node) != XML_DOM_ELEMENT) node = xml_node_next(node);
    return node;
}

static XMQNode *fx_first(XMQNode *e) { return fx_element(xml_node_first_child(e)); }
static XMQNode *fx_next(XMQNode *e) { return fx_element(xml_node_next(e)); }

static bool fx_is(XMQNode *e, const char *name) { return !strcmp(xml_node_name(e), name); }

/** The value of the attribute, malloced, or NULL. */
static char *fx_attr(XMQNode *e, const char *name)
{
    XMQAttr *a = xml_node_get_attr(e, name, NULL);
    if (!a) return NULL;
    return xml_node_string_value(xml_attr_node(a));
}

static void fx_append_attr(IXMLFromXml *x, XMQNode *e, const char *name)
{
    char *v = fx_attr(e, name);
    if (v) membuffer_append(x->mb, v);
    free(v);
}

/** The text as ixml strings, eg "it's" or 'say "hi"'. A string can not span lines, so a
    newline or carriage return is written as #a or #d. Every piece gets the prefix (a tmark
    or +) and the pieces are separated by sep: ", " in an alt and "; " in a charset. */
static void fx_strings(IXMLFromXml *x, const char *s, const char *prefix, const char *sep)
{
    bool first = true;
    if (*s == 0)
    {
        // An empty string, the ixml grammar reader reports it.
        membuffer_append(x->mb, prefix);
        membuffer_append(x->mb, "\"\"");
        return;
    }
    while (*s)
    {
        if (!first) membuffer_append(x->mb, sep);
        first = false;
        membuffer_append(x->mb, prefix);
        if (*s == '\n' || *s == '\r')
        {
            membuffer_append(x->mb, *s == '\n' ? "#a" : "#d");
            s++;
            continue;
        }
        membuffer_append(x->mb, "\"");
        while (*s && *s != '\n' && *s != '\r')
        {
            if (*s == '"') membuffer_append(x->mb, "\"\""); // A quote is doubled.
            else
            {
                char c[2] = { *s, 0 };
                membuffer_append(x->mb, c);
            }
            s++;
        }
        membuffer_append(x->mb, "\"");
    }
}

/** A character of a range, from or to: #hex as it is, else the character as a string. */
static void fx_range_char(IXMLFromXml *x, const char *v)
{
    if (v[0] == '#' && v[1] != 0) membuffer_append(x->mb, v);
    else fx_strings(x, v, "", "; ");
}

/** A literal or an insertion: its string or hex. */
static void fx_string_or_hex(IXMLFromXml *x, XMQNode *e, const char *prefix, const char *sep)
{
    char *string = fx_attr(e, "string");
    char *hex = fx_attr(e, "hex");
    if (string) fx_strings(x, string, prefix, sep);
    else if (hex)
    {
        membuffer_append(x->mb, prefix);
        membuffer_append(x->mb, "#");
        membuffer_append(x->mb, hex);
    }
    else fx_error(x, "%s needs a string or a hex attribute", xml_node_name(e));
    free(string);
    free(hex);
}

static void fx_alts(IXMLFromXml *x, XMQNode *e);

static void fx_member(IXMLFromXml *x, XMQNode *m)
{
    char *string = fx_attr(m, "string");
    char *hex = fx_attr(m, "hex");
    char *from = fx_attr(m, "from");
    char *to = fx_attr(m, "to");
    char *code = fx_attr(m, "code");
    if (string) fx_strings(x, string, "", "; ");
    else if (hex) { membuffer_append(x->mb, "#"); membuffer_append(x->mb, hex); }
    else if (from && to) { fx_range_char(x, from); membuffer_append(x->mb, "-"); fx_range_char(x, to); }
    else if (code) membuffer_append(x->mb, code);
    else fx_error(x, "member needs a string, hex, from and to, or code attribute", NULL);
    free(string); free(hex); free(from); free(to); free(code);
}

static void fx_factor(IXMLFromXml *x, XMQNode *e)
{
    if (fx_is(e, "nonterminal"))
    {
        fx_append_attr(x, e, "mark");
        fx_append_attr(x, e, "name");
        char *alias = fx_attr(e, "alias");
        if (alias) { membuffer_append(x->mb, ">"); membuffer_append(x->mb, alias); }
        free(alias);
    }
    else if (fx_is(e, "literal"))
    {
        char *tmark = fx_attr(e, "tmark");
        fx_string_or_hex(x, e, tmark ? tmark : "", ", ");
        free(tmark);
    }
    else if (fx_is(e, "insertion"))
    {
        fx_string_or_hex(x, e, "+", ", ");
    }
    else if (fx_is(e, "inclusion") || fx_is(e, "exclusion"))
    {
        fx_append_attr(x, e, "tmark");
        if (fx_is(e, "exclusion")) membuffer_append(x->mb, "~");
        membuffer_append(x->mb, "[");
        bool first = true;
        for (XMQNode *m = fx_first(e); m; m = fx_next(m))
        {
            if (fx_is(m, "comment")) continue;
            if (!fx_is(m, "member")) { fx_error(x, "unexpected %s in a character set", xml_node_name(m)); continue; }
            if (!first) membuffer_append(x->mb, "; ");
            first = false;
            fx_member(x, m);
        }
        membuffer_append(x->mb, "]");
    }
    else if (fx_is(e, "option") || fx_is(e, "repeat0") || fx_is(e, "repeat1"))
    {
        // option: factor. repeat0 and repeat1: factor and an optional sep with a factor.
        XMQNode *factor = NULL, *sep = NULL;
        for (XMQNode *c = fx_first(e); c; c = fx_next(c))
        {
            if (fx_is(c, "comment")) continue;
            if (fx_is(c, "sep")) sep = c;
            else if (!factor) factor = c;
            else fx_error(x, "%s has more than one factor", xml_node_name(e));
        }
        if (!factor) { fx_error(x, "%s has no factor", xml_node_name(e)); return; }
        fx_factor(x, factor);
        const char *op = fx_is(e, "option") ? "?" : fx_is(e, "repeat0") ? "*" : "+";
        membuffer_append(x->mb, op);
        if (sep)
        {
            XMQNode *s = fx_first(sep);
            while (s && fx_is(s, "comment")) s = fx_next(s);
            if (!s || fx_is(e, "option")) { fx_error(x, "%s has a bad sep", xml_node_name(e)); return; }
            membuffer_append(x->mb, op);
            fx_factor(x, s);
        }
    }
    else if (fx_is(e, "alts"))
    {
        membuffer_append(x->mb, "(");
        fx_alts(x, e);
        membuffer_append(x->mb, ")");
    }
    else
    {
        fx_error(x, "unexpected element %s in an ixml grammar", xml_node_name(e));
    }
}

/** The alt children of a rule or alts: "a, b; c". */
static void fx_alts(IXMLFromXml *x, XMQNode *e)
{
    bool first_alt = true;
    for (XMQNode *alt = fx_first(e); alt; alt = fx_next(alt))
    {
        if (fx_is(alt, "comment")) continue;
        if (!fx_is(alt, "alt")) { fx_error(x, "expected alt, not %s", xml_node_name(alt)); continue; }
        if (!first_alt) membuffer_append(x->mb, "; ");
        first_alt = false;
        bool first = true;
        for (XMQNode *f = fx_first(alt); f; f = fx_next(f))
        {
            if (fx_is(f, "comment")) continue;
            if (!first) membuffer_append(x->mb, ", ");
            first = false;
            fx_factor(x, f);
        }
    }
}

char *ixml_text_from_xml_grammar(XmlDom *dom, char **error)
{
    IXMLFromXml x;
    x.mb = new_membuffer();
    x.error = NULL;

    XMQNode *root = xml_dom_root_element(dom);
    if (!root || !fx_is(root, "ixml"))
    {
        fx_error(&x, "the root element must be ixml, not %s", root ? xml_node_name(root) : "nothing");
    }
    for (XMQNode *e = root ? fx_first(root) : NULL; e && !x.error; e = fx_next(e))
    {
        if (fx_is(e, "comment")) continue;
        if (fx_is(e, "prolog"))
        {
            // <prolog><version string="1.0"/></prolog>
            XMQNode *v = fx_first(e);
            char *version = v && fx_is(v, "version") ? fx_attr(v, "string") : NULL;
            if (!version) { fx_error(&x, "prolog needs a version with a string", NULL); break; }
            membuffer_append(x.mb, "ixml version ");
            fx_strings(&x, version, "", ", ");
            membuffer_append(x.mb, ".\n");
            free(version);
        }
        else if (fx_is(e, "rule"))
        {
            fx_append_attr(&x, e, "mark");
            fx_append_attr(&x, e, "name");
            char *alias = fx_attr(e, "alias");
            if (alias) { membuffer_append(x.mb, ">"); membuffer_append(x.mb, alias); }
            free(alias);
            membuffer_append(x.mb, ": ");
            fx_alts(&x, e);
            membuffer_append(x.mb, ".\n");
        }
        else
        {
            fx_error(&x, "unexpected element %s in an ixml grammar", xml_node_name(e));
        }
    }

    if (x.error)
    {
        free_membuffer_and_free_content(x.mb);
        *error = x.error;
        return NULL;
    }
    membuffer_append_null(x.mb);
    *error = NULL;
    return free_membuffer_but_return_trimmed_content(x.mb);
}

static int compare_code_points(const void *a, const void *b)
{
    int x = *(const int*)a;
    int y = *(const int*)b;
    return (x > y) - (x < y);
}

// Is the code point in the part (a range or a unicode category) of a charset?
static bool charset_part_has_code(IXMLCharsetPart *p, int c)
{
    if (!p->category[0]) return c >= p->from && c <= p->to;

    const char **cat_part = unicode_lookup_category_parts(p->category);
    for (; *cat_part; ++cat_part)
    {
        UnicodeCategoryRange *cat = NULL;
        size_t cat_len = 0;
        if (!unicode_get_category_part(*cat_part, &cat, &cat_len))
        {
            fprintf(stderr, "Invalid unicode category: %s\n", *cat_part);
            exit(1);
        }
        if (category_has_code(c, cat, cat_len)) return true;
    }
    return false;
}

void scan_content_fixup_charsets(XMQParseState *state, const char *start, const char *stop)
{
    // A byte for every possible unicode code point, 0x110000 = 1 MB, set when the code
    // point has been seen in the content of this or an earlier parse with this grammar.
    if (state->used_unicodes == NULL)
    {
        state->used_unicodes = (char*)malloc(0x110000);
        memset(state->used_unicodes, 0, 0x110000);
    }
    char *already_used = state->used_unicodes;

    /* If we are parsing using --lines, ie each input line in the file is reparsed using the ixml grammar.
       Hej aaa!
       Hej aaa!
       Hej aab!

       with the ixml grammar:
       name = -'Hej ', [L]+, '!'.

       then the first line adds "H e j a" to the charset [L].
       the second line adds nothing more.
       the third line adds "b" to the charset [L].

       Only the code points that are new in this content are collected and tested against
       the charsets, so the work is proportional to the new code points, not to the size
       of the charsets (eg [L] has more than 100000 code points) or to all unicode code points.
    */

    int *new_codes = NULL;
    size_t num_new = 0;
    size_t new_size = 0;

    const char *i = start;
    while (i < stop)
    {
        int uc = 0;
        size_t len = 0;
        bool ok = decode_utf8(i, stop, &uc, &len);
        i += len;
        // The content was checked to be valid UTF-8 before the scan, never index
        // the tables beyond the last code point #10ffff.
        if (!ok || uc < 0 || uc > 0x10ffff) continue;

        if (!already_used[uc])
        {
            already_used[uc] = 1;
            if (num_new == new_size)
            {
                new_size = new_size ? new_size*2 : 64;
                new_codes = (int*)realloc(new_codes, new_size*sizeof(int));
                check_malloc(new_codes);
            }
            new_codes[num_new++] = uc;

            char buf[16];
            snprintf(buf,16, "#%x", uc);
            IXMLTerminal *t = (IXMLTerminal*)hashmap_get(state->ixml_terminals_map, buf);
            if (t == NULL)
            {
                // Add terminal not in the grammar, but found inside the input content to be parsed.
                // This gives us better error messages from yaep. Instead of "No such token" we
                // get syntax error at line:col.
                t = new_ixml_terminal();
                t->name = strdup(buf);
                t->code = uc;
                add_yaep_terminal(state, t);
            }
        }
    }

    // No new code points, the charset rules from earlier parses are already complete.
    if (num_new == 0) return;

    // The rules are added in code point order within each part of a charset.
    qsort(new_codes, num_new, sizeof(int), compare_code_points);

    for (size_t n = 0; n < state->ixml_non_terminals->size; ++n)
    {
        IXMLNonTerminal *nt = (IXMLNonTerminal*)vector_element_at(state->ixml_non_terminals, n);
        if (!nt->charset) continue;

        bool include = nt->name[0] != '~';
        char tmark = 0;
        if ((nt->name[0] == '[' && nt->name[1] == '-') ||
            (nt->name[1] == '[' && nt->name[2] == '-'))
        {
            tmark = '-';
        }

        if (include)
        {
            // Including, the new code points in each part of the charset, a category
            // one category part (eg Lu Ll Lt Lm Lo for L) at a time.
            for (IXMLCharsetPart *p = nt->charset->first; p; p = p->next)
            {
                if (!p->category[0])
                {
                    for (size_t k = 0; k < num_new; ++k)
                    {
                        int c = new_codes[k];
                        if (c >= p->from && c <= p->to) add_single_char_rule(state, nt, c, '-', tmark);
                    }
                    continue;
                }
                const char **cat_part = unicode_lookup_category_parts(p->category);
                for (; *cat_part; ++cat_part)
                {
                    UnicodeCategoryRange *cat = NULL;
                    size_t cat_len = 0;
                    if (!unicode_get_category_part(*cat_part, &cat, &cat_len))
                    {
                        fprintf(stderr, "Invalid unicode category: %s\n", *cat_part);
                        exit(1);
                    }
                    for (size_t k = 0; k < num_new; ++k)
                    {
                        int c = new_codes[k];
                        if (category_has_code(c, cat, cat_len)) add_single_char_rule(state, nt, c, '-', tmark);
                    }
                }
            }
        }
        else
        {
            // Excluding, the new code points that are in no part of the charset.
            for (size_t k = 0; k < num_new; ++k)
            {
                bool should_add = true;
                for (IXMLCharsetPart *p = nt->charset->first; p; p = p->next)
                {
                    if (charset_part_has_code(p, new_codes[k]))
                    {
                        should_add = false;
                        break;
                    }
                }
                if (should_add)
                {
                    add_single_char_rule(state, nt, new_codes[k], '-', tmark);
                }
            }
        }
    }

    free(new_codes);
}

void add_yaep_tmp_terminals_to_rule(XMQParseState *state, IXMLRule *rule, char mark)
{
    for (size_t i = 0; i < state->ixml_tmp_terminals->size; ++i)
    {
        IXMLTerminal *te = (IXMLTerminal*)state->ixml_tmp_terminals->elements[i];
        IXMLTerminal *t = (IXMLTerminal*)hashmap_get(state->ixml_terminals_map, te->name);
        if (t == NULL)
        {
            // This terminal was not already in the map. Add it.
            add_yaep_terminal(state, te);
            t = te;
        }
        else
        {
            // This terminal was already in the map. Free the terminal and add a
            // pointer the already stored termina to the rule.
            free_ixml_terminal(te);
        }
        add_yaep_term_to_rule(state, mark, t, NULL);
        state->ixml_tmp_terminals->elements[i] = NULL;
    }
}

void allocate_yaep_tmp_terminals(XMQParseState *state)
{
    assert(state->ixml_tmp_terminals == NULL);
    state->ixml_tmp_terminals = vector_create();
}

void free_yaep_tmp_terminals(XMQParseState *state)
{
    // Only free the vector, the content is copied to another array.
    vector_free(state->ixml_tmp_terminals);
    state->ixml_tmp_terminals = NULL;
}

void free_yaep_tmp_terminals_and_content(XMQParseState *state)
{
    // Free the tmp terminals themselves.
    vector_free_and_values(state->ixml_tmp_terminals, (FreeFuncPtr)free_ixml_terminal);
    state->ixml_tmp_terminals = NULL;
}

bool has_ixml_tmp_terminals(XMQParseState *state)
{
    assert(state->ixml_tmp_terminals);

    return state->ixml_tmp_terminals->size > 0;
}

bool has_more_than_one_ixml_tmp_terminals(XMQParseState *state)
{
    assert(state->ixml_tmp_terminals);

    return state->ixml_tmp_terminals->size > 1;
}

IXMLRule *new_ixml_rule()
{
    IXMLRule *r = (IXMLRule*)calloc(1, sizeof(IXMLRule));
    r->rule_name = new_ixml_nonterminal();
    r->rhs_terms = vector_create();
    return r;
}

void free_ixml_rule(IXMLRule *r)
{
    if (r->rule_name) free_ixml_nonterminal(r->rule_name);
    r->rule_name = NULL;
    vector_free_and_values(r->rhs_terms, (FreeFuncPtr)free_ixml_term);
    r->rhs_terms = NULL;
    free(r);
}

IXMLTerminal *new_ixml_terminal()
{
    IXMLTerminal *t = (IXMLTerminal*)calloc(1, sizeof(IXMLTerminal));
    return t;
}

void free_ixml_terminal(IXMLTerminal *t)
{
    if (t->name) free(t->name);
    t->name = NULL;
    free(t);
}

IXMLNonTerminal *new_ixml_nonterminal()
{
    IXMLNonTerminal *nt = (IXMLNonTerminal*)calloc(1, sizeof(IXMLNonTerminal));
    return nt;
}

IXMLNonTerminal *copy_ixml_nonterminal(IXMLNonTerminal *nt)
{
    IXMLNonTerminal *t = (IXMLNonTerminal*)calloc(1, sizeof(IXMLNonTerminal));
    t->name = strdup(nt->name);
    return t;
}

void free_ixml_nonterminal(IXMLNonTerminal *nt)
{
    if (nt->name) free(nt->name);
    nt->name = NULL;
    if (nt->alias) free(nt->alias);
    nt->alias = NULL;
    if (nt->charset) free_ixml_charset(nt->charset);
    nt->charset = NULL;
    free(nt);
}

void free_ixml_term(IXMLTerm *t)
{
    t->t = NULL;
    t->nt = NULL;
    free(t);
}

IXMLCharset *new_ixml_charset(bool exclude)
{
    IXMLCharset *cs = (IXMLCharset*)calloc(1, sizeof(IXMLCharset));
    cs->exclude = exclude;
    return cs;
}

void new_ixml_charset_part(IXMLCharset *cs, int from, int to, const char *category)
{
    IXMLCharsetPart *csp = (IXMLCharsetPart*)calloc(1, sizeof(IXMLCharsetPart));
    csp->from = from;
    csp->to = to;
    // A unicode category has one or two letters (eg L or Lu), category[3] keeps its NUL.
    size_t n = 0;
    while (n < sizeof(csp->category)-1 && category[n]) { csp->category[n] = category[n]; n++; }
    csp->category[n] = 0;
    if (cs->last == NULL)
    {
        cs->first = cs->last = csp;
    }
    else
    {
        cs->last->next = csp;
        cs->last = csp;
    }
}

void free_ixml_charset(IXMLCharset *cs)
{
    IXMLCharsetPart *i = cs->first;
    while (i)
    {
        IXMLCharsetPart *next = i->next;
        i->next = NULL;
        free(i);
        i = next;
    }
    cs->first = NULL;
    cs->last = NULL;
    free(cs);
}

char *generate_rule_name(XMQParseState *state)
{
    char buf[16];
    snprintf(buf, 15, "|%d", state->num_generated_rules);
    state->num_generated_rules++;
    return strdup(buf);
}

char *generate_charset_rule_name(IXMLCharset *cs, char mark)
{
    char *buf = (char*)malloc(1024);
    buf[0] = 0;

    if (cs->exclude) strcat(buf, "~");
    strcat(buf, "[");
    char m[2];
    m[0] = mark;
    m[1] = 0;
    if (mark != 0 && mark != ' ') strcat(buf, m);

    IXMLCharsetPart *i = cs->first;
    bool first = true;

    while (i)
    {
        if (!first) { strcat(buf, ";"); } else { first = false; }
        if (i->category[0]) strcat(buf, i->category);
        else
        {
            if (i->from != i->to)
            {
                char s[16];
                snprintf(s, 16, "#%x-#%x", i->from, i->to);
                strcat(buf, s);
            }
            else
            {
                char s[16];
                snprintf(s, 16, "#%x", i->from);
                strcat(buf, s);
            }
        }
        i = i->next;
    }

    strcat(buf, "]");
    return buf;
}

void make_last_term_optional(XMQParseState *state)
{
    // Compose an anonymous rule.
    // 'a'? is replaced with the nonterminal /17 (for example)
    // Then /17 can be either 'a' or the empty string.
    // /17 : 'a'.
    // /17 : .

    // Pop the last term.
    IXMLTerm *term = (IXMLTerm*)vector_pop_back(state->ixml_rule->rhs_terms);

    IXMLNonTerminal *nt = new_ixml_nonterminal();
    nt->name = generate_rule_name(state);

    add_yaep_nonterminal(state, nt);
    add_yaep_term_to_rule(state, '-', NULL, nt);

    stack_push(state->ixml_rule_stack, state->ixml_rule);

    state->ixml_rule = new_ixml_rule();
    state->ixml_rule->mark = '-';
    vector_push_back(state->ixml_rules, state->ixml_rule);

    free_ixml_nonterminal(state->ixml_rule->rule_name);
    state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

    // Single term in this rule alternative. Use the mark stored on the term,
    // state->ixml_mark can be stale, e.g. after a group (a, @b)? it is the mark of @b.
    add_yaep_term_to_rule(state, term->mark, term->t, term->nt);
    free(term);
    term = NULL;

    state->ixml_rule = new_ixml_rule();
    state->ixml_rule->mark = '-';

    vector_push_back(state->ixml_rules, state->ixml_rule);

    free_ixml_nonterminal(state->ixml_rule->rule_name);
    state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

    // No terms in this rule alternative!

    state->ixml_rule = (IXMLRule*)stack_pop(state->ixml_rule_stack);
}

void make_last_term_repeat(XMQParseState *state)
{
    // Compose an anonymous rule.
    // 'a'+ is replaced with the nonterminal /17 (for example)
    // Then /17 can be either 'a' or the /17, 'a'
    // /17 = "a".
    // /17 = /17, "a".

    // Pop the last term.
    IXMLTerm *term = (IXMLTerm*)vector_pop_back(state->ixml_rule->rhs_terms);

    IXMLNonTerminal *nt = new_ixml_nonterminal();
    nt->name = generate_rule_name(state);

    add_yaep_nonterminal(state, nt);
    add_yaep_term_to_rule(state, '-', NULL, nt);

    stack_push(state->ixml_rule_stack, state->ixml_rule);

    // Build first alternative rule: /17 = 'a'.
    state->ixml_rule = new_ixml_rule();
    state->ixml_rule->mark = '-';
    vector_push_back(state->ixml_rules, state->ixml_rule);

    free_ixml_nonterminal(state->ixml_rule->rule_name);
    state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

    // 'a'
    add_yaep_term_to_rule(state, term->mark, term->t, term->nt);

    // Build second alternative rule: /17 = /17, 'a'.
    state->ixml_rule = new_ixml_rule();
    state->ixml_rule->mark = '-';
    vector_push_back(state->ixml_rules, state->ixml_rule);

    free_ixml_nonterminal(state->ixml_rule->rule_name);
    state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

    // /17, 'a'
    add_yaep_term_to_rule(state, '-', NULL, nt);
    add_yaep_term_to_rule(state, term->mark, term->t, term->nt);

    free(term);
    term = NULL;

    state->ixml_rule = (IXMLRule*)stack_pop(state->ixml_rule_stack);
}

void make_last_term_repeat_infix(XMQParseState *state)
{
    // Compose an anonymous rule.
    // 'a'++'b' is replaced with the nonterminal /17 (for example)
    // Then /17 can be either 'a' or the /17, 'a'
    // /17 = "a".
    // /17 = /17, "b", "a".

    // Pop the last two terms.
    IXMLTerm *infix = (IXMLTerm*)vector_pop_back(state->ixml_rule->rhs_terms);
    IXMLTerm *term = (IXMLTerm*)vector_pop_back(state->ixml_rule->rhs_terms);

    IXMLNonTerminal *nt = new_ixml_nonterminal();
    nt->name = generate_rule_name(state);

    add_yaep_nonterminal(state, nt);
    add_yaep_term_to_rule(state, '-', NULL, nt);

    stack_push(state->ixml_rule_stack, state->ixml_rule);

    // Build first alternative rule: /17 = 'a'.
    state->ixml_rule = new_ixml_rule();
    state->ixml_rule->mark = '-';
    vector_push_back(state->ixml_rules, state->ixml_rule);

    free_ixml_nonterminal(state->ixml_rule->rule_name);
    state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

    // 'a'
    add_yaep_term_to_rule(state, term->mark, term->t, term->nt);

    // Build second alternative rule: /17 = /17, 'b', 'a'.
    state->ixml_rule = new_ixml_rule();
    state->ixml_rule->mark = '-';
    vector_push_back(state->ixml_rules, state->ixml_rule);

    free_ixml_nonterminal(state->ixml_rule->rule_name);
    state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

    // /17, 'b', 'a'
    add_yaep_term_to_rule(state, '-', NULL, nt);
    add_yaep_term_to_rule(state, infix->mark, infix->t, infix->nt);
    add_yaep_term_to_rule(state, term->mark, term->t, term->nt);

    free(term);
    free(infix);
    term = NULL;
    infix = NULL;

    state->ixml_rule = (IXMLRule*)stack_pop(state->ixml_rule_stack);
}

void make_last_term_repeat_zero(XMQParseState *state)
{
    // Compose an anonymous rule.
    // 'a'+ is replaced with the nonterminal /17 (for example)
    // Then /17 can be either 'a' or the /17, 'a'
    // /17 = .
    // /17 = /17 | "a".

    // Pop the last term.
    IXMLTerm *term = (IXMLTerm*)vector_pop_back(state->ixml_rule->rhs_terms);

    IXMLNonTerminal *nt = new_ixml_nonterminal();
    nt->name = generate_rule_name(state);

    add_yaep_nonterminal(state, nt);
    add_yaep_term_to_rule(state, '-', NULL, nt);

    stack_push(state->ixml_rule_stack, state->ixml_rule);

    // Build first alternative rule: /17 = .
    state->ixml_rule = new_ixml_rule();
    state->ixml_rule->mark = '-';
    vector_push_back(state->ixml_rules, state->ixml_rule);

    free_ixml_nonterminal(state->ixml_rule->rule_name);
    state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

    // Build second alternative rule: /17 = /17, 'a'.
    state->ixml_rule = new_ixml_rule();
    state->ixml_rule->mark = '-';
    vector_push_back(state->ixml_rules, state->ixml_rule);

    free_ixml_nonterminal(state->ixml_rule->rule_name);
    state->ixml_rule->rule_name = copy_ixml_nonterminal(nt);

    // /17, 'a'
    add_yaep_term_to_rule(state, '-', NULL, nt);
    add_yaep_term_to_rule(state, term->mark, term->t, term->nt);

    free(term);
    term = NULL;

    state->ixml_rule = (IXMLRule*)stack_pop(state->ixml_rule_stack);
}

void make_last_term_repeat_zero_infix(XMQParseState *state)
{
    make_last_term_repeat_infix(state);
    make_last_term_optional(state);
}

void ixml_print_grammar(XMQParseState *state)
{
    if (false && xmq_trace_enabled_)
    {
        HashMapIterator *i = hashmap_iterate(state->ixml_terminals_map);

        const char *name;
        void *val;
        while (hashmap_next_key_value(i, &name, &val))
        {
            IXMLTerminal *t = (IXMLTerminal*)val;
            printf("TERMINAL %s %d\n", t->name, t->code);
        }

        hashmap_free_iterator(i);

        for (size_t i = 0; i < state->ixml_rules->size; ++i)
        {
            IXMLRule *r = (IXMLRule*)vector_element_at(state->ixml_rules, i);
            printf("RULE %c%s\n", r->mark?r->mark:' ', r->rule_name->name);

            for (size_t j = 0; j < r->rhs_terms->size; ++j)
            {
                IXMLTerm *term = (IXMLTerm*)vector_element_at(r->rhs_terms, j);
                if (term->type == IXML_TERMINAL)
                {
                    printf("   T %c%s %d\n", term->mark?term->mark:' ', term->t->name, term->t->code);
                }
                else
                {
                    printf("   R %c%s \n", term->mark?term->mark:' ', term->nt->name);
                }
            }
        }
    }
}

