/*
 * regexp.c: generic and extensible Regular Expression engine
 *
 * Basically designed with the purpose of compiling regexps for
 * the variety of validation/schemas mechanisms now available in
 * XML related specifications these include:
 *    - XML-1.0 DTD validation
 *    - XML Schemas structure part 1
 *    - XML Schemas Datatypes part 2 especially Appendix F
 *    - RELAX-NG/TREX i.e. the counter proposal
 *
 * See Copyright for the status of this software.
 *
 * Author: Daniel Veillard
 */

// The macros of libxml2 xmlregexp.c, not shared with the other parts (dist/xmq.c is one file).
#undef MAX_PUSH
#undef ERROR
#undef NEXT
#undef CUR
#undef NXT
#undef NEXTL
#undef XML_REG_STRING_SEPARATOR
#undef PREV
#undef AM_AUTOMATA_RNG
#undef REGEXP_ALL_COUNTER
#undef REGEXP_ALL_LAX_COUNTER
#undef XML_MAX_ITEMS
#undef XML_REGEXP_ERR_NO_MEMORY
#undef XML_REGEXP_ERR_COMPILE

/* The libxml2 XML_MAX_ITEMS (private/memory.h). */
#define XML_MAX_ITEMS 1000000000 /* 1 billion */

/* The ctxt->error values, the libxml2 XML_ERR_NO_MEMORY and XML_REGEXP_COMPILE_ERROR. */
#define XML_REGEXP_ERR_NO_MEMORY 2
#define XML_REGEXP_ERR_COMPILE 1450

/* #define DEBUG_REGEXP */

#define MAX_PUSH 10000000

#define ERROR(str)							\
    ctxt->error = XML_REGEXP_ERR_COMPILE;				\
    xml_regexp_err_compile(ctxt, str);
#define NEXT ctxt->cur++
#define CUR (*((const unsigned char *) ctxt->cur))
#define NXT(index)									\
    (((size_t)(ctxt->cur + index - ctxt->string) < ctxt->len)				\
      ? ((const unsigned char *) ctxt->cur)[index] : 0)

#define NEXTL(l) ctxt->cur += l;
#define XML_REG_STRING_SEPARATOR '|'
/*
 * Need PREV to check on a '-' within a Character Group. May only be used
 * when it's guaranteed that cur is not at the beginning of ctxt->string!
 */
#define PREV (ctxt->cur[-1])

/************************************************************************
 *									*
 *	String, memory and character helpers (libxml2 xmlstring.c,	*
 *	private/memory.h and chvalid.h)					*
 *									*
 ************************************************************************/

/* Port of xmlStrdup. */
static char *
xml_reg_strdup(const char *cur) {
    size_t len;
    char *ret;

    if (cur == NULL)
        return(NULL);
    len = strlen(cur);
    ret = (char *) malloc(len + 1);
    if (ret == NULL)
        return(NULL);
    memcpy(ret, cur, len + 1);
    return(ret);
}

/* Port of xmlStrndup. */
static char *
xml_reg_strndup(const char *cur, int len) {
    char *ret;

    if ((cur == NULL) || (len < 0))
        return(NULL);
    ret = (char *) malloc((size_t) len + 1);
    if (ret == NULL)
        return(NULL);
    memcpy(ret, cur, len);
    ret[len] = 0;
    return(ret);
}

/* Port of xmlStrEqual. */
static int
xml_reg_str_equal(const char *str1, const char *str2) {
    if (str1 == str2) return(1);
    if (str1 == NULL) return(0);
    if (str2 == NULL) return(0);
    return(strcmp(str1, str2) == 0);
}

/* Port of xmlStrchr. */
static const char *
xml_reg_strchr(const char *str, char val) {
    if (str == NULL) return(NULL);
    while (*str != 0) {
        if (*str == val) return(str);
        str++;
    }
    return(NULL);
}

/* Port of xmlGrowCapacity (private/memory.h). */
static int
xml_reg_grow_capacity(int capacity, size_t elemSize, int min, int max) {
    int extra;

    if (capacity <= 0) {
        return(min);
    }

    if ((capacity >= max) ||
        ((size_t) capacity > SIZE_MAX / 2 / elemSize))
        return(-1);

    /* Grow by 50% */
    extra = (capacity + 1) / 2;

    if (capacity > max - extra)
        return(max);

    return(capacity + extra);
}

/* Port of xmlGetUTF8Char. */
static int
xml_reg_get_utf8_char(const char *str, int *len) {
    const unsigned char *utf = (const unsigned char *) str;
    unsigned int c;

    if (utf == NULL)
        goto error;
    if (len == NULL)
        goto error;

    c = utf[0];
    if (c < 0x80) {
        if (*len < 1)
            goto error;
        /* 1-byte code */
        *len = 1;
    } else {
        if ((*len < 2) || ((utf[1] & 0xc0) != 0x80))
            goto error;
        if (c < 0xe0) {
            if (c < 0xc2)
                goto error;
            /* 2-byte code */
            *len = 2;
            c = (c & 0x1f) << 6;
            c |= utf[1] & 0x3f;
        } else {
            if ((*len < 3) || ((utf[2] & 0xc0) != 0x80))
                goto error;
            if (c < 0xf0) {
                /* 3-byte code */
                *len = 3;
                c = (c & 0xf) << 12;
                c |= (utf[1] & 0x3f) << 6;
                c |= utf[2] & 0x3f;
                if ((c < 0x800) || ((c >= 0xd800) && (c < 0xe000)))
                    goto error;
            } else {
                if ((*len < 4) || ((utf[3] & 0xc0) != 0x80))
                    goto error;
                *len = 4;
                /* 4-byte code */
                c = (c & 0x7) << 18;
                c |= (utf[1] & 0x3f) << 12;
                c |= (utf[2] & 0x3f) << 6;
                c |= utf[3] & 0x3f;
                if ((c < 0x10000) || (c >= 0x110000))
                    goto error;
            }
        }
    }
    return(c);

error:
    if (len != NULL)
	*len = 0;
    return(-1);
}

/* Port of xmlIsCharQ (IS_CHAR), the XML 1.0 Char production. */
static int
xml_reg_is_char(int c) {
    if (c < 0x100)
        return(((0x9 <= c) && (c <= 0xa)) || (c == 0xd) || (0x20 <= c));
    return(((0x100 <= c) && (c <= 0xd7ff)) ||
           ((0xe000 <= c) && (c <= 0xfffd)) ||
           ((0x10000 <= c) && (c <= 0x10ffff)));
}

