/**
 * Port of xmlAutomataNewState.
 *
 * Create a new disconnected state in the automata
 *
 * @param am  an automata
 * @returns the new state or NULL in case of error
 */
XmlAutomataState *
xml_automata_new_state(XmlAutomata *am) {
    if (am == NULL)
	return(NULL);
    return(xml_reg_state_push(am));
}

/**
 * Port of xmlAutomataNewEpsilon.
 *
 * If `to` is NULL, this creates first a new target state in the automata
 * and then adds an epsilon transition from the `from` state to the
 * target state
 *
 * @param am  an automata
 * @param from  the starting point of the transition
 * @param to  the target point of the transition or NULL
 * @returns the target state or NULL in case of error
 */
XmlAutomataState *
xml_automata_new_epsilon(XmlAutomata *am, XmlAutomataState *from,
		      XmlAutomataState *to) {
    if ((am == NULL) || (from == NULL))
	return(NULL);
    xml_fa_generate_epsilon_transition(am, from, to);
    if (to == NULL)
	return(am->state);
    return(to);
}

/**
 * Port of xmlAutomataNewAllTrans.
 *
 * If `to` is NULL, this creates first a new target state in the automata
 * and then adds a an ALL transition from the `from` state to the
 * target state. That transition is an epsilon transition allowed only when
 * all transitions from the `from` node have been activated.
 *
 * @param am  an automata
 * @param from  the starting point of the transition
 * @param to  the target point of the transition or NULL
 * @param lax  allow to transition if not all all transitions have been activated
 * @returns the target state or NULL in case of error
 */
XmlAutomataState *
xml_automata_new_all_trans(XmlAutomata *am, XmlAutomataState *from,
		       XmlAutomataState *to, int lax) {
    if ((am == NULL) || (from == NULL))
	return(NULL);
    xml_fa_generate_all_transition(am, from, to, lax);
    if (to == NULL)
	return(am->state);
    return(to);
}

/**
 * Port of xmlAutomataNewCounter.
 *
 * Create a new counter
 *
 * @param am  an automata
 * @param min  the minimal value on the counter
 * @param max  the maximal value on the counter
 * @returns the counter number or -1 in case of error
 */
int
xml_automata_new_counter(XmlAutomata *am, int min, int max) {
    int ret;

    if (am == NULL)
	return(-1);

    ret = xml_reg_get_counter(am);
    if (ret < 0)
	return(-1);
    am->counters[ret].min = min;
    am->counters[ret].max = max;
    return(ret);
}

/**
 * Port of xmlAutomataNewCountedTrans.
 *
 * If `to` is NULL, this creates first a new target state in the automata
 * and then adds an epsilon transition from the `from` state to the target state
 * which will increment the counter provided
 *
 * @param am  an automata
 * @param from  the starting point of the transition
 * @param to  the target point of the transition or NULL
 * @param counter  the counter associated to that transition
 * @returns the target state or NULL in case of error
 */
XmlAutomataState *
xml_automata_new_counted_trans(XmlAutomata *am, XmlAutomataState *from,
		XmlAutomataState *to, int counter) {
    if ((am == NULL) || (from == NULL) || (counter < 0))
	return(NULL);
    xml_fa_generate_counted_epsilon_transition(am, from, to, counter);
    if (to == NULL)
	return(am->state);
    return(to);
}

/**
 * Port of xmlAutomataNewCounterTrans.
 *
 * If `to` is NULL, this creates first a new target state in the automata
 * and then adds an epsilon transition from the `from` state to the target state
 * which will be allowed only if the counter is within the right range.
 *
 * @param am  an automata
 * @param from  the starting point of the transition
 * @param to  the target point of the transition or NULL
 * @param counter  the counter associated to that transition
 * @returns the target state or NULL in case of error
 */
XmlAutomataState *
xml_automata_new_counter_trans(XmlAutomata *am, XmlAutomataState *from,
		XmlAutomataState *to, int counter) {
    if ((am == NULL) || (from == NULL) || (counter < 0))
	return(NULL);
    xml_fa_generate_counted_transition(am, from, to, counter);
    if (to == NULL)
	return(am->state);
    return(to);
}

/**
 * Port of xmlAutomataCompile.
 *
 * Compile the automata into a Reg Exp ready for being executed.
 * The automata should be free after this point.
 *
 * @param am  an automata
 * @returns the compiled regexp or NULL in case of error
 */
XmlRegexp *
xml_automata_compile(XmlAutomata *am) {
    XmlRegexp *ret;

    if ((am == NULL) || (am->error != 0)) return(NULL);
    xml_fa_eliminate_epsilon_transitions(am);
    if (am->error != 0)
        return(NULL);
    /* xml_fa_computes_determinism(am); */
    ret = xml_reg_epx_from_parse(am);

    return(ret);
}

/**
 * Port of xmlAutomataIsDeterminist.
 *
 * Checks if an automata is determinist.
 *
 * @param am  an automata
 * @returns 1 if true, 0 if not, and -1 in case of error
 */
int
xml_automata_is_determinist(XmlAutomata *am) {
    int ret;

    if (am == NULL)
	return(-1);

    ret = xml_fa_computes_determinism(am);
    return(ret);
}

